#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
generate_slots.py
=================
Generador automático de slots de animación para Cerdo_1.

USO:
    python generate_slots.py recorrido.json [--start-slot N] [--start-frame N] [--output-dir ./slots]

ARGUMENTOS:
    recorrido.json      Archivo JSON con la trayectoria grabada
    --start-slot N      Número del primer slot a generar (default: 1)
    --start-frame N     Frame de Blender donde comienza la animación (default: 1)
    --output-dir DIR    Carpeta donde se guardan los .py generados (default: ./slots_generados)

LÓGICA DE DETECCIÓN:
    - Z sube entre dos puntos consecutivos  → slot saltar_subir  (2 puntos, 18 frames)
    - Z baja entre dos puntos consecutivos  → slot saltar_bajar  (2 puntos, 35 frames)
    - Punto identico al anterior (mismo x/y/z) → slot parada    (2 puntos, 45 frames — NUEVO 2026-07-08)
    - Z constante en N puntos consecutivos  → slot caminar       (N puntos, 60 frames)
"""

import json
import os
import sys
import math
from datetime import date

def _woodcut_module():
    import importlib.util
    spec = importlib.util.spec_from_file_location('_cerdo_1_woodcut_generator', os.path.join(os.path.dirname(__file__), 'woodcut_animation.py'))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

def is_woodcut(value):
    return str(value).lower() in ('cortar_madera_inferior', 'cortar_madera_intermedio', 'cortar_madera_superior')

def group_segments(key_points):
    return _woodcut_module().group_woodcut_points(key_points, _group_segments_legacy, as_dict=True)

def generate_cortar_madera(slot_index, start_frame, points, today, root_rot=(0,0,-90), variant='cortar_madera_intermedio'):
    from pathlib import Path
    module = _woodcut_module()
    if not is_woodcut(variant):
        raise ValueError(variant)
    source_path = Path(__file__).with_name('woodcut_animation.py')
    source = source_path.read_text(encoding='utf-8')
    asset = next((p/'objetos/vanilla/oak_planks/oak_planks.blend' for p in source_path.parents if (p/'objetos/vanilla/oak_planks/oak_planks.blend').is_file()), None)
    pos = points[0]['coordinates']
    config = dict(slot=slot_index, start_frame=start_frame, variant=variant,
                  position=[pos[k] for k in 'xyz'], root_rot=list(root_rot),
                  root_name='cerdo_1', armature_name='pig.arma_cerdo_1', axe_name='stone_axe',
                  wood_asset=str(asset) if asset else '')
    end_frame = start_frame + module.WOODCUT_FRAMES - 1
    metadata = dict(name=f'slot_{slot_index:03d}_{variant}.py', movement_type=variant,
                    start_frame=start_frame,end_frame=end_frame,total_frames=module.WOODCUT_FRAMES,fps=24)
    code = source + '\n\nWOODCUT_CONFIG = ' + repr(config)
    code += '\nANIMATION_INFO = ' + repr(metadata)
    code += '\nSTART_FRAME = '+str(start_frame)+'\nEND_FRAME = '+str(end_frame)
    code += '\ndef execute_animation(player_parts=None, start_frame=None, end_frame=None):\n    return execute_woodcut(WOODCUT_CONFIG, start_frame, end_frame)\n'
    return code, end_frame


