# --- COLOCAR ANTORCHA (relativo al frame 0 del slot) ---
# ACTUALIZADO (Kebyn, 2026-08-21): duracion bajada de 48 a 30 frames.
# RESTAURADO (Kebyn): vuelve a existir el tercer tramo "vuelta a
# POSE_PARADO" (frame 15->29), eliminado en una revision anterior y
# repuesto a pedido de Kebyn. El root/Empty "cerdo_1" queda FIJO en
# points[0] durante TODO el slot (ver generate_colocar_antorcha() /
# ROOT_LOCATION_DATA) -- el personaje no camina ni un frame mientras
# se agacha, planta la antorcha y vuelve a pararse; el tramo "caminar"
# inyectado automaticamente despues (mismos 2 puntos, ver
# group_segments()) es el unico que recorre la distancia real hasta
# donde quedo la antorcha, arrancando desde ESE MISMO punto (points[0])
# en el que arranco colocar_antorcha, no desde points[1]. Estructura:
#   frame 0  -> POSE_PARADO (misma postura de pie que generate_parada(),
#               ver _PARADO_POSE mas arriba)
#   frame 15 -> pose capturada "inclinado_colocando_antorcha.json"
#               (personaje=cerdo_1, frame 25 en el archivo fuente, 22 huesos,
#               formato local_space/rotation_euler_rad -- solo se usan los
#               mismos 14 huesos animables que POSE_PARADO) -- ver
#               MID_FRAME_COLOCAR_ANTORCHA arriba, mismo frame en el que
#               aparece la antorcha
#   frame 29 -> vuelta a POSE_PARADO (ver RETURN_TO_PARADO_FRAMES mas
#               abajo, construida en tiempo de generacion a partir de
#               esta misma pose de frame 0, no hardcodeada aca)
# Interpolacion smoothstep en el tramo 0->15 (parado->agachado). Formato
# del diccionario sin cambios (bone -> {frame: (x,y,z)} en radianes).

