# ============================================================
# DETECCIÓN Y AGRUPACIÓN DE SEGMENTOS
# ============================================================


import importlib.util as _jump_import
from pathlib import Path as _JumpPath
_jump_spec = _jump_import.spec_from_file_location(__name__ + '_jump_motion', _JumpPath(__file__).with_name('jump_motion.py'))
_adaptive_jump = _jump_import.module_from_spec(_jump_spec)
_jump_spec.loader.exec_module(_adaptive_jump)
jump_frame_count = _adaptive_jump.jump_frame_count

def detect_movement_type(p_current, p_next):
    if p_current.get('tipo_segmento','AUTO') == 'SALTAR':
        z0,z1=round(p_current['coordinates']['z'],2),round(p_next['coordinates']['z'],2)
        return 'saltar_subir' if z1>z0 else 'saltar_bajar' if z1<z0 else 'saltar_horizontal'
    if is_woodcut(p_current.get("tipo_segmento", "AUTO")):
        return p_current["tipo_segmento"].lower()
    """Detecta el tipo de movimiento entre dos puntos.

    NUEVO 2026-07-08 (paradas): si el punto es identico al anterior (misma
    x/y/z — sin distancia XY y sin cambio de Z), se clasifica como
    "parada" en vez de "caminar". Esto replica exactamente el mismo
    criterio que usa `_detectar_movimiento_recorrido()` en el pipeline
    Python (cerdo_1_story_generator.py) para que la duracion calculada de
    un lado coincida con lo que este addon realmente reproduce en
    Blender. Antes de este fix, un punto duplicado se interpretaba como
    una caminata de distancia cero (0 frames) — el gap del "parada" se
    perdia por completo.

    FIX (Kebyn, 2026-08-23): las coordenadas que llegan aca ya vienen
    redondeadas a 4 decimales (export_recorrido_json/export_to_dict en
    path_recorder.py), pero eso resulto insuficiente -- se reporto un
    caso real donde dos faces "iguales a la vista" (mismo texture, misma
    posicion visible en el escenario) difieren en menos de un
    centimetro por ruido geometrico de la malla del escenario, quedando
    por encima de 4 decimales y clasificandose como salto en vez de
    parada. Se compara con una tolerancia de 2 decimales (0.01) -- la
    MISMA precision que el panel del Paso 1 le muestra al usuario (ver
    round(pt.coords[...], 2) en panels.py) -- para que si dos puntos se
    ven iguales en la lista de "Coordenadas seleccionadas", tambien se
    clasifiquen como el mismo punto (parada) aca. Debe coincidir con el
    mismo cambio en _detect_move()/_detect_move_geom() (path_recorder.py).
    """
    # NUEVO (Kebyn, 2026-08-21): override manual "colocar_antorcha" --
    # igual que "parada" (tipo_segmento), pero aca el punto SIGUIENTE es
    # la coordenada REAL consecutiva del recorrido (el suelo donde se
    # planta la antorcha), no un duplicado. Se marca en
    # CERDO_1PathPoint.tipo_segmento (Paso 1) y viaja hasta aca via el
    # campo "tipo_segmento" de p_current (ver key_points en
    # path_recorder.py). Tiene prioridad sobre la deteccion geometrica --
    # funciona sin importar si el tramo real seria caminar/subir/bajar.
    if p_current.get('tipo_segmento') == 'COLOCAR_ANTORCHA':
        return 'colocar_antorcha'
    # NUEVO (Kebyn): override manual 'golpe_estomago_1' -- misma
    # arquitectura que 'colocar_antorcha' (ver comentario de arriba):
    # abarca este punto y el siguiente (coordenadas reales, sin
    # duplicar), prioridad sobre la deteccion geometrica. Debe coincidir
    # con el mismo override en _detect_move() (path_recorder.py).
    if p_current.get('tipo_segmento') == 'GOLPE_ESTOMAGO_1':
        return 'golpe_estomago_1'
    # NUEVO (Kebyn, 2026-08-22): override manual 'colocar_mesa_de_crafteo'
    # -- misma arquitectura que 'colocar_antorcha' (ver comentario de
    # arriba): abarca este punto y el siguiente (coordenadas reales, sin
    # duplicar), prioridad sobre la deteccion geometrica. Debe coincidir
    # con el mismo override en _detect_move() (path_recorder.py).
    if p_current.get('tipo_segmento') == 'COLOCAR_MESA_CRAFTEO':
        return 'colocar_mesa_de_crafteo'
    # NUEVO (Kebyn, "crear pared NxN bloques"): override manual
    # 'crear_pared_nxn' -- misma arquitectura que 'colocar_mesa_de_crafteo'
    # de arriba (abarca este punto y el siguiente, coordenadas reales, sin
    # duplicar), prioridad sobre la deteccion geometrica. Debe coincidir
    # con el mismo override en _detect_move() (path_recorder.py).
    if p_current.get('tipo_segmento') == 'CREAR_PARED_NXN':
        return 'crear_pared_nxn'
    # NUEVO (Kebyn): override manual 'levantarse_1' -- misma arquitectura
    # que 'golpe_estomago_1' de arriba, sin duplicar punto. Debe coincidir
    # con el mismo override en _detect_move() (path_recorder.py).
    if p_current.get('tipo_segmento') == 'LEVANTARSE_1':
        return 'levantarse_1'
    # NUEVO (Kebyn): override manual 'levantarse_2' -- misma arquitectura
    # que 'levantarse_1' de arriba (segunda variante de animacion
    # importada de Mixamo de levantarse del suelo), sin duplicar punto.
    # Debe coincidir con el mismo override en _detect_move()
    # (path_recorder.py).
    if p_current.get('tipo_segmento') == 'LEVANTARSE_2':
        return 'levantarse_2'
    # NUEVO (Kebyn): override manual 'arrodillarse_1' -- misma
    # arquitectura que 'levantarse_1'/'levantarse_2'/'golpe_estomago_1'
    # de arriba, sin duplicar punto. Debe coincidir con el mismo
    # override en _detect_move() (path_recorder.py).
    if p_current.get('tipo_segmento') == 'ARRODILLARSE_1':
        return 'arrodillarse_1'
    # NUEVO (Kebyn): override manual 'conversar_1' -- misma arquitectura
    # que 'arrodillarse_1'/'levantarse_1'/'golpe_estomago_1' de arriba,
    # sin duplicar punto. Debe coincidir con el mismo override en
    # _detect_move() (path_recorder.py).
    if p_current.get('tipo_segmento') == 'CONVERSAR_1':
        return 'conversar_1'
    # NUEVO (Kebyn): override manual 'resbalarse_1' -- misma arquitectura
    # que 'arrodillarse_1'/'levantarse_1'/'golpe_estomago_1' de arriba,
    # sin duplicar punto. Debe coincidir con el mismo override en
    # _detect_move() (path_recorder.py).
    if p_current.get('tipo_segmento') == 'RESBALARSE_1':
        return 'resbalarse_1'

    c0 = p_current['coordinates']
    c1 = p_next['coordinates']
    x0, y0, z0 = round(c0['x'], 2), round(c0['y'], 2), round(c0['z'], 2)
    x1, y1, z1 = round(c1['x'], 2), round(c1['y'], 2), round(c1['z'], 2)
    if x0 == x1 and y0 == y1 and z0 == z1:
        # FIX (Kebyn, 2026-08-23 v2): "parada" solo si el punto esta
        # EXPLICITAMENTE marcado como PARADA -- ver docstring de arriba
        # y el mismo cambio en _detect_move() (path_recorder.py). En
        # AUTO, una coordenada repetida resuelve como "caminar" (en el
        # lugar, sin desplazarse -- generate_caminar() ya clampea
        # dist_total a un minimo de 0.0001 para este caso).
        if p_current.get('tipo_segmento') == 'PARADA':
            return 'parada'
        return 'caminar'
    dz = z1 - z0
    if dz > 0:
        return 'saltar_subir'
    elif dz < 0:
        return 'saltar_bajar'
    else:
        return 'caminar'


def _group_segments_legacy(key_points):
    """
    Recorre los puntos y agrupa consecutivos del mismo tipo en segmentos.
    Retorna lista de dicts: {type, points}
    Reglas:
      - saltar_subir / saltar_bajar: siempre exactamente 2 puntos
      - parada: siempre exactamente 2 puntos (identicos) — NUEVO 2026-07-08
      - colocar_antorcha: siempre exactamente 2 puntos (coordenadas
        REALES consecutivas, override manual) — NUEVO 2026-08-21
      - caminar: todos los consecutivos con Z igual (y sin ser el mismo
        punto) se agrupan en un solo slot
    """
    segments = []
    i = 0
    n = len(key_points)

    _ACCION_OVERRIDES = ('COLOCAR_ANTORCHA', 'GOLPE_ESTOMAGO_1', 'COLOCAR_MESA_CRAFTEO', 'CREAR_PARED_NXN', 'LEVANTARSE_1', 'LEVANTARSE_2', 'ARRODILLARSE_1', 'CONVERSAR_1', 'RESBALARSE_1')

    while i < n - 1:
        # FIX (Kebyn, 2026-08-23 tris, "se crea un caminar fantasma entre
        # Parada y Levantarse/etc"): key_points[i] es el punto DUPLICADO
        # que _expand_points_with_paradas() inserta justo despues de una
        # "parada" (marcado con es_parada_dup=True, sin tipo_segmento
        # propio). Si el punto SIGUIENTE ya esta marcado manualmente con
        # uno de los overrides de accion puntual (Levantarse, colocar
        # antorcha, etc), ese punto va a arrancar su propio segmento de
        # accion en la proxima vuelta del while de todos modos (mismo
        # mecanismo de siempre: el override se mira sobre el p0 de CADA
        # tramo). El tramo [duplicado_parada -> punto_marcado] no
        # necesita su propio segmento "caminar": el personaje esta fijo
        # en el lugar de la parada, no caminando, mientras arranca la
        # accion siguiente -- generar un "caminar" aca era exactamente
        # el segmento fantasma reportado. Se salta este punto sin emitir
        # ningun segmento (el punto marcado pasa a ser el nuevo p0 en la
        # proxima iteracion, disparando su override normalmente). Debe
        # coincidir con el mismo fix en _group_segments()
        # (path_recorder.py).
        if (key_points[i].get('es_parada_dup')
                and key_points[i].get('tipo_segmento', 'AUTO') not in _ACCION_OVERRIDES
                and key_points[i + 1].get('tipo_segmento', 'AUTO') in _ACCION_OVERRIDES):
            i += 1
            continue

        move_type = detect_movement_type(key_points[i], key_points[i + 1])

        if move_type in ('saltar_subir', 'saltar_bajar', 'saltar_horizontal', 'parada'):
            # Siempre 2 puntos
            segments.append({
                'type': move_type,
                'points': [key_points[i], key_points[i + 1]]
            })
            i += 1

        elif move_type in ('colocar_antorcha', 'golpe_estomago_1', 'colocar_mesa_de_crafteo', 'crear_pared_nxn', 'levantarse_1', 'levantarse_2', 'arrodillarse_1', 'conversar_1', 'resbalarse_1'):
            # NUEVO (Kebyn): 'golpe_estomago_1' y 'colocar_mesa_de_crafteo'
            # comparten exactamente la misma arquitectura de
            # fusion-con-el-caminar-siguiente que 'colocar_antorcha' -- ver
            # generate_golpe_estomago_1()/generate_colocar_mesa_crafteo(),
            # que tambien dejan el root fijo en key_points[i] durante todo
            # el slot. 'levantarse_2' es la segunda variante de
            # 'levantarse_1', misma arquitectura exacta. 'arrodillarse_1'
            # (ver generate_arrodillarse_1()) idem. 'conversar_1' (ver
            # generate_conversar_1()) idem. 'resbalarse_1' (ver
            # generate_resbalarse_1()) idem.
            segments.append({
                'type': move_type,
                'points': [key_points[i], key_points[i + 1]]
            })
            # FIX (Kebyn, teletransportacion post-antorcha): generate_colocar_antorcha()
            # deja el root FIJO en key_points[i] durante todo el slot (solo se
            # agacha/planta la antorcha en key_points[i+1], nunca camina hasta
            # ahi). Se necesita un tramo "caminar" de alcance de key_points[i]
            # a key_points[i+1] justo despues de plantar la antorcha, para que
            # el recorrido continue sin desplazamientos repentinos.
            #
            # FIX (Kebyn, 2026-08-21 quater, "piernas no abren bien en el 2do
            # ciclo"): antes ese tramo de alcance se agregaba como un segmento
            # "caminar" SEPARADO de 2 puntos, y el caminar real que le seguia
            # quedaba agrupado aparte en OTRO segmento "caminar" -- cada uno
            # hornea su propio walk_cycle arrancando en fase 0 (accion aislada
            # en su propia pista NLA), y fase 0 no es pose neutral sino mitad
            # de zancada con una rodilla flexionada. Terminar un segmento a
            # mitad de zancada y arrancar el siguiente de golpe en fase 0
            # producia el pop de piernas reportado. Ahora se fusiona el tramo
            # de alcance con TODO el caminar real que le sigue en UN SOLO
            # segmento "caminar" continuo -- mismo mecanismo de agrupacion que
            # la rama 'else' de abajo, arrancando en key_points[i] -- asi
            # walk_cycle es continuo de punta a punta. Debe coincidir con el
            # mismo cambio en _group_segments() (path_recorder.py).
            #
            # FIX (Kebyn, "deberian haber solo 3 segmentos en vez de 4"):
            # si key_points[i] y key_points[i+1] son la MISMA coordenada
            # (redondeada a 2 decimales -- misma tolerancia que
            # detect_movement_type()), no hay ninguna distancia real que
            # recorrer -- el personaje ya esta parado exactamente donde
            # tendria que "caminar". Antes esto igual generaba un segmento
            # "caminar" de alcance con distancia 0 (caminar en el lugar,
            # ver generate_caminar()/dist_total clampeado a 0.0001), un
            # segmento visible y audible (walk cycle completo) que no
            # desplaza al personaje ni un centimetro -- el caso tipico es
            # exactamente este (points[i+1] reutilizado solo para marcar
            # una Parada en el mismo lugar, ver
            # _compute_object_placement_target()). En ese caso se omite
            # el tramo de alcance por completo y se avanza directo a
            # key_points[i+1] para que el siguiente segmento (la Parada)
            # arranque inmediatamente despues del slot de colocacion, sin
            # un "caminar" de por medio. Debe coincidir con el mismo
            # cambio en _group_segments() (path_recorder.py).
            _c0 = key_points[i]['coordinates']
            _c1 = key_points[i + 1]['coordinates']
            _same_coord = (round(_c0['x'], 2) == round(_c1['x'], 2)
                           and round(_c0['y'], 2) == round(_c1['y'], 2)
                           and round(_c0['z'], 2) == round(_c1['z'], 2))
            # FIX (Kebyn, 2026-08-23 cuater, "se crea un caminar fantasma
            # entre Levantarse/etc y la Parada que sigue"): mismo problema
            # que el fix de arriba pero al reves -- si key_points[i+1] (el
            # punto de destino de la accion) esta marcado manualmente como
            # PARADA, el personaje se va a quedar quieto ahi de todos modos
            # apenas empiece esa parada; el tramo de "alcance" caminando
            # hasta ahi no aporta nada (un walk cycle completo de ~12f
            # inmediatamente seguido de quedarse parado) y es exactamente
            # el segmento fantasma reportado. Se trata igual que el caso
            # de coordenadas identicas de arriba: se omite el tramo de
            # alcance y se avanza directo a key_points[i+1] para que la
            # Parada arranque inmediatamente despues de la accion. Debe
            # coincidir con el mismo cambio en _group_segments()
            # (path_recorder.py).
            _dest_es_parada = key_points[i + 1].get('tipo_segmento', 'AUTO') == 'PARADA'
            if _same_coord or _dest_es_parada:
                i = i + 1
            else:
                group = [key_points[i], key_points[i + 1]]
                j = i + 1
                while j < n - 1 and detect_movement_type(key_points[j], key_points[j + 1]) == 'caminar':
                    group.append(key_points[j + 1])
                    j += 1
                segments.append({'type': 'caminar', 'points': group})
                # FIX (Kebyn, bug "antorchas/paradas en secuencia se tragan",
                # 2026-08-21): antes era `i = j + 1`, que saltaba el punto en
                # key_points[j] por completo -- ese es exactamente el punto
                # donde termina el caminar fusionado, y tambien el punto donde
                # DEBE empezar el siguiente segmento especial si el usuario lo
                # marco como otra 'colocar_antorcha' o como 'parada' (via el
                # punto duplicado que inserta _expand_points_with_paradas()).
                # Con `i = j + 1` ese punto nunca se volvia a evaluar como
                # p_current en la vuelta siguiente del while principal, asi que
                # su propio segmento (plantar la 2da antorcha, o la pausa) jamas
                # se generaba -- se veia como un salto de coordenada sin
                # animacion (o como una parada que "no se reproduce"). La rama
                # 'caminar' de mas abajo (sin antorcha de por medio) nunca tuvo
                # este bug porque reutiliza el mismo indice `i` para el bucle y
                # para la reanudacion -- aca replicamos ese mismo patron:
                # reanudar en key_points[j] (no j+1), dandole a ese punto su
                # turno de iniciar su propio segmento.
                i = j

        else:  # caminar
            # Agrupar todos los consecutivos con Z constante
            group = [key_points[i]]
            while i < n - 1 and detect_movement_type(key_points[i], key_points[i + 1]) == 'caminar':
                group.append(key_points[i + 1])
                i += 1
            segments.append({
                'type': 'caminar',
                'points': group
            })

    # NUEVO (Kebyn, "crear pared no debe pedir punto siguiente"): el while
    # de arriba nunca evalua el ULTIMO punto como p0 (condicion `i < n - 1`),
    # asi que si el usuario marca justo ese ultimo punto como "Crear pared
    # NxN bloques" no hay key_points[i+1] real con el que emparejarlo. En
    # vez de bloquear la opcion, se agrega su propio segmento duplicando el
    # punto (key_points[-1], key_points[-1]) -- el mismo caso "degenerado"
    # (points[0]==points[1]) que _compute_object_placement_target()/
    # _compute_wall_grid_coords() ya saben manejar: la pared se planta
    # OBJECT_PLACEMENT_FORWARD_STEP (1m) adelante del personaje segun su
    # orientacion actual (root_rot heredado del ultimo tramo caminado, ver
    # _cur_rot en path_recorder.py), sin necesitar una coordenada real
    # distinta. Debe coincidir con el mismo cambio en _group_segments()
    # (path_recorder.py).
    if key_points and key_points[-1].get('tipo_segmento', 'AUTO') == 'CREAR_PARED_NXN':
        segments.append({
            'type': 'crear_pared_nxn',
            'points': [key_points[-1], key_points[-1]]
        })

    return segments

# ============================================================
# GENERADORES DE CÓDIGO PYTHON POR TIPO
# ============================================================

def _fmt_keyframes(kf_dict, start_frame):
    """Convierte keyframes relativos (0-based) a frames absolutos y los formatea como código Python."""
    lines = []
    lines.append("KEYFRAME_DATA = {")
    for bone, frames in kf_dict.items():
        lines.append(f"    '{bone}': {{")
        for rel_frame, rot in frames.items():
            abs_frame = start_frame + rel_frame
            lines.append(f"        {abs_frame}: ({rot[0]:.6f}, {rot[1]:.6f}, {rot[2]:.6f}),")
        lines.append("    },")
    lines.append("}")
    return "\n".join(lines)


def _fmt_trajectory(points):
    """Formatea los puntos de trayectoria como código Python."""
    lines = ["EMBEDDED_TRAJECTORY_POINTS = ["]
    for p in points:
        c = p['coordinates']
        lines.append("    {")
        lines.append(f"        \"index\": {p['index']},")
        lines.append(f"        \"coordinates\": {{\"x\": {c['x']}, \"y\": {c['y']}, \"z\": {c['z']}}},")
        lines.append(f"        \"texture\": \"{p['texture']}\",")
        lines.append(f"        \"face_index\": \"{p['face_index']}\"")
        lines.append("    },")
    lines.append("]")
    return "\n".join(lines)


# ============================================================
# ANIMACION IMPORTADA (.py) PARA PUNTOS DE "PARADA" — Kebyn, 2026-09-13
# ============================================================
# NUEVO: en el Paso 1 (Path Recorder / panels.py), un punto marcado como
# "Parada" ahora puede tener asociado un archivo .py de animacion
# importada (ver CERDO_1PathPoint.parada_anim_file en path_recorder.py),
# tipicamente exportado por el conversor de Mixamo -- mismo formato que
# slot_001_parado_discutiendo_dba2c3.py: un modulo con un diccionario
# module-level KEYFRAME_DATA de bone -> {frame: (rx, ry, rz)}. Estas 3
# funciones cargan ese archivo en tiempo de GENERACION (dentro de
# Blender, no en el .py exportado) y arman el bloque de codigo que
# generate_parada() embebe en el slot generado -- misma arquitectura que
# ya usan golpe_estomago_1/levantarse_1/levantarse_2/arrodillarse_1/
# conversar_1/resbalarse_1 con sus propios *_KEYFRAME_DATA fijos, salvo
# que aca el diccionario no esta hardcodeado en este archivo sino que se
# lee dinamicamente del .py que el usuario eligio en el panel.

def _load_animation_data_from_anim_file(filepath):
    """Carga KEYFRAME_DATA y EYES_DATA desde un .py exportado.

    EYES_DATA conserva la animacion propia de las mallas de ojos:
    transformaciones del objeto, visibilidad y valores de shape keys. Los
    frames de ambos bloques se normalizan juntos a 0-based para que el clip
    mantenga su sincronizacion al insertarlo en cualquier slot.

    Carga KEYFRAME_DATA desde un script .py de animacion importada
    (ej. exportado por el conversor de Mixamo). Se ejecuta el archivo
    como modulo (misma confianza que el resto del pipeline: son scripts
    generados por el propio conversor de Kebyn, no contenido externo) y
    se lee su KEYFRAME_DATA module-level.

    Normaliza los frames del archivo a 0-based (frame minimo del
    archivo -> 0) para poder reusar _fmt_keyframes() tal cual (misma
    convencion 0-based que ya usan GOLPE_ESTOMAGO_1_KEYFRAME_DATA y el
    resto de las animaciones Mixamo hardcodeadas en este archivo).

    Devuelve bones Euler, ojos, transforms completos de bones, geometria de
    ojos y frame_count. Los dos bloques nuevos son opcionales para conservar
    compatibilidad con exportaciones anteriores.
    archivo no existe, no se pudo ejecutar, o no define KEYFRAME_DATA
    (fallback silencioso -- generate_parada() vuelve entonces a la pose
    estatica 'parado' de siempre).
    """
    import os as _os_mod
    import importlib.util as _ilu_mod

    if not filepath or not _os_mod.path.isfile(filepath):
        print(f"generate_parada: archivo de animacion importada no encontrado: {filepath}")
        return None, {}, {}, {}, None

    try:
        _spec = _ilu_mod.spec_from_file_location("_cerdo_1_parada_anim_importada", filepath)
        _mod = _ilu_mod.module_from_spec(_spec)
        _spec.loader.exec_module(_mod)
    except Exception as e:
        print(f"generate_parada: no se pudo ejecutar el archivo de animacion importada '{filepath}': {e}")
        return None, {}, {}, {}, None

    raw_kf = getattr(_mod, "KEYFRAME_DATA", None)
    if not raw_kf:
        print(f"generate_parada: '{filepath}' no define KEYFRAME_DATA -- se ignora")
        return None, {}, {}, {}, None

    raw_eyes = getattr(_mod, "EYES_DATA", None) or {}
    raw_bone_transforms = getattr(_mod, "BONE_TRANSFORM_DATA", None) or {}
    raw_eye_geometry = getattr(_mod, "EYE_SHAPE_GEOMETRY", None) or {}
    all_frames = [int(f) for bone_kf in raw_kf.values() for f in bone_kf.keys()]
    for bone_data in raw_bone_transforms.values():
        for channel in ("location", "rotation_quaternion", "rotation_euler", "scale"):
            values = bone_data.get(channel, {}) if isinstance(bone_data, dict) else {}
            if isinstance(values, dict):
                all_frames.extend(int(f) for f in values.keys())
    for eye_data in raw_eyes.values():
        if not isinstance(eye_data, dict):
            continue
        for channel in ("location", "rotation_quaternion", "rotation_euler", "scale", "hide_viewport", "hide_render"):
            values = eye_data.get(channel, {})
            if isinstance(values, dict):
                all_frames.extend(int(f) for f in values.keys())
        for values in eye_data.get("shape_keys", {}).values():
            if isinstance(values, dict):
                all_frames.extend(int(f) for f in values.keys())
    if not all_frames:
        return None, {}, {}, {}, None

    src_min = min(all_frames)
    src_max = max(all_frames)
    normalized = {
        bone: {int(f) - src_min: rot for f, rot in bone_kf.items()}
        for bone, bone_kf in raw_kf.items()
    }
    normalized_bone_transforms = {}
    for bone_name, bone_data in raw_bone_transforms.items():
        if not isinstance(bone_data, dict):
            continue
        dst = {}
        for channel in ("location", "rotation_quaternion", "rotation_euler", "scale"):
            values = bone_data.get(channel, {})
            if isinstance(values, dict) and values:
                dst[channel] = {int(f) - src_min: value for f, value in values.items()}
        if dst:
            normalized_bone_transforms[bone_name] = dst
    normalized_eyes = {}
    for eye_name, eye_data in raw_eyes.items():
        if not isinstance(eye_data, dict):
            continue
        dst = {}
        for channel in ("location", "rotation_quaternion", "rotation_euler", "scale", "hide_viewport", "hide_render"):
            values = eye_data.get(channel, {})
            if isinstance(values, dict) and values:
                dst[channel] = {int(f) - src_min: value for f, value in values.items()}
        shape_keys = {}
        for key_name, values in eye_data.get("shape_keys", {}).items():
            if isinstance(values, dict) and values:
                shape_keys[key_name] = {int(f) - src_min: value for f, value in values.items()}
        if shape_keys:
            dst["shape_keys"] = shape_keys
        if dst:
            normalized_eyes[eye_name] = dst
    frame_count = src_max - src_min + 1
    return normalized, normalized_eyes, normalized_bone_transforms, raw_eye_geometry, frame_count


def _load_keyframe_data_from_anim_file(filepath):
    """Compatibilidad con llamadas antiguas que solo necesitan bones."""
    bones, _eyes, _bone_transforms, _eye_geometry, frame_count = _load_animation_data_from_anim_file(filepath)
    return bones, frame_count


def _build_parada_pose_estatica_block(slot_index):
    """Bloque de codigo (texto ya formateado, mismo patron que `traj`/
    `kf` en generate_golpe_estomago_1 etc.) que resetea los bones
    animables a la postura base 'parado' (ver parado.json) -- el
    comportamiento de 'Parada' de toda la vida, usado cuando el punto NO
    tiene ninguna animacion .py importada asociada. Extraido tal cual de
    generate_parada() para poder alternar con
    _build_parada_anim_importada_block() sin duplicar el resto de la
    plantilla del slot.
    """
    arm_action_name = f"slot_{slot_index:03d}_cerdo_1_parada_bones_rest"
    return f'''_BONES_RESET = [
    'Body_cerdo_1', 'Body:Bend_cerdo_1', 'Body:Bend_cerdo_1', 'Body:Bend_cerdo_1',
    'Head_cerdo_1', 'Head_cerdo_1',
    'Leg:FR_cerdo_1', 'Leg:FR:Bend_cerdo_1',
    'Leg:FL_cerdo_1',  'Leg:FL:Bend_cerdo_1',
    'Leg:BR_cerdo_1', 'Leg:BR:Bend_cerdo_1',
    'Leg:BL_cerdo_1',  'Leg:BL:Bend_cerdo_1',
]

_PARADO_POSE = {{
    'Body_cerdo_1':        (0.0, 0.0, 0.0),
    'Body:Bend_cerdo_1':       (0.0, 0.0, 0.0),
    'Body:Bend_cerdo_1':      (0.0, 0.0, 0.0),
    'Body:Bend_cerdo_1':      (0.0, 0.0, 0.0),
    'Head_cerdo_1':        (0.0, 0.0, 0.0),
    'Head_cerdo_1':        (0.0, 0.0, 0.0),
    'Leg:FR_cerdo_1':  (0.0, 0.0, 0.0),
    'Leg:FR:Bend_cerdo_1':  (0.0, 0.0, 0.0),
    'Leg:FL_cerdo_1':   (0.0, 0.0, 0.0),
    'Leg:FL:Bend_cerdo_1':   (0.0, 0.0, 0.0),
    'Leg:BR_cerdo_1':  (0.0, 0.0, 0.0),
    'Leg:BR:Bend_cerdo_1':   (0.0, 0.0, 0.0),
    'Leg:BL_cerdo_1':   (0.0, 0.0, 0.0),
    'Leg:BL:Bend_cerdo_1':    (0.0, 0.0, 0.0),
}}

_arm_action_name = '{arm_action_name}'

if not armature.animation_data:
    armature.animation_data_create()
_arm_existing = bpy.data.actions.get(_arm_action_name)
if _arm_existing:
    bpy.data.actions.remove(_arm_existing)
_arm_action = bpy.data.actions.new(name=_arm_action_name)
armature.animation_data.action = _arm_action

_bones_reset_ok = 0
for _bone_name in _BONES_RESET:
    _bone = armature.pose.bones.get(_bone_name)
    if not _bone:
        continue
    _bone.rotation_mode = 'XYZ'
    _bone.rotation_euler = _PARADO_POSE.get(_bone_name, (0.0, 0.0, 0.0))
    _bone.keyframe_insert(data_path="rotation_euler", frame=start_frame)
    _bone.keyframe_insert(data_path="rotation_euler", frame=end_frame)
    _bones_reset_ok += 1

if armature.animation_data.action:
    for fcurve in _get_fcurves(armature.animation_data.action):
        for kp in fcurve.keyframe_points:
            kp.interpolation = 'CONSTANT'

print("   " + str(_bones_reset_ok) + " bones puestos en postura 'parado' (parado.json) para canvas limpio")
# MIRAR ALREDEDOR (cerdo de Minecraft parado): la cabeza gira hacia puntos al azar (izquierda/derecha y arriba/abajo),
# se queda mirando un momento y vuelve al frente al final; el cuerpo y las patas no se mueven.
import random as _rnd_mira
_cabeza = armature.pose.bones.get('Head_cerdo_1')
if _cabeza is not None and end_frame - start_frame >= 30:
    _r = _rnd_mira.Random(SLOT_INDEX * 7 + 3)
    _f = start_frame; _mira = (0.0, 0.0, 0.0)
    while True:
        _quieto = _r.randint(20, 45); _giro = _r.randint(8, 14)
        if _f + _quieto + _giro > end_frame - 14:
            break
        _f += _quieto
        _cabeza.rotation_euler = _mira; _cabeza.keyframe_insert(data_path='rotation_euler', frame=_f)
        _lado = math.radians(_r.choice((-1, 1)) * _r.uniform(25.0, 55.0))   # gira la cabeza a un lado y la INCLINA hacia ese lado
        _mira = (math.radians(_r.uniform(-12.0, 20.0)), -0.35 * _lado, _lado)
        _f += _giro
        _cabeza.rotation_euler = _mira; _cabeza.keyframe_insert(data_path='rotation_euler', frame=_f)
    _cabeza.rotation_euler = _mira; _cabeza.keyframe_insert(data_path='rotation_euler', frame=max(_f, end_frame - 10))
    _cabeza.rotation_euler = (0.0, 0.0, 0.0); _cabeza.keyframe_insert(data_path='rotation_euler', frame=end_frame)
    for _fc in _get_fcurves(armature.animation_data.action):
        if 'Head_cerdo_1' in _fc.data_path:
            for _kp in _fc.keyframe_points:
                _kp.interpolation = 'BEZIER'
    print('   cerdo: mira alrededor durante la parada')
'''


def _build_parada_anim_importada_block(anim_kf_data, start_frame, slot_index, anim_src_label):
    """Bloque de codigo (texto ya formateado -- mismo patron que
    `_fmt_keyframes` y lo que ya usan golpe_estomago_1/levantarse_1/
    conversar_1/etc.) que aplica una animacion .py IMPORTADA durante
    esta parada, en vez del reset a la postura estatica 'parado'.

    `anim_kf_data` ya viene normalizado a 0-based (ver
    _load_keyframe_data_from_anim_file) para poder reusar
    `_fmt_keyframes` sin cambios. El root sigue inmovil (ver
    ROOT_LOCATION_DATA/ROOT_ROTATION_DATA en generate_parada, sin
    cambios) -- solo el cuerpo reproduce el clip importado.
    """
    kf_code = _fmt_keyframes(anim_kf_data, start_frame)
    arm_action_name = f"slot_{slot_index:03d}_cerdo_1_parada_anim_importada"
    label_literal = repr(anim_src_label)
    return f'''{kf_code}

_arm_action_name = '{arm_action_name}'

if not armature.animation_data:
    armature.animation_data_create()
_arm_existing = bpy.data.actions.get(_arm_action_name)
if _arm_existing:
    bpy.data.actions.remove(_arm_existing)
_arm_action = bpy.data.actions.new(name=_arm_action_name)
armature.animation_data.action = _arm_action

_bones_reset_ok = 0
if IMPORTED_BONE_TRANSFORM_DATA:
    for _bone_name, _channels in IMPORTED_BONE_TRANSFORM_DATA.items():
        _bone = armature.pose.bones.get(_bone_name)
        if not _bone:
            continue
        _bone.rotation_mode = 'QUATERNION' if _channels.get("rotation_quaternion") else 'XYZ'
        for _channel in ("location", "rotation_quaternion", "rotation_euler", "scale"):
            for _rel_frame, _value in _channels.get(_channel, {{}}).items():
                setattr(_bone, _channel, _value)
                _bone.keyframe_insert(data_path=_channel, frame=start_frame + int(_rel_frame))
        _bones_reset_ok += 1
else:
    for _bone_name, _bone_kf in KEYFRAME_DATA.items():
        _bone = armature.pose.bones.get(_bone_name)
        if not _bone:
            continue
        _bone.rotation_mode = 'XYZ'
        for _frame, _rot in _bone_kf.items():
            _bone.rotation_euler = _rot
            _bone.keyframe_insert(data_path="rotation_euler", frame=_frame)
        _bones_reset_ok += 1

if armature.animation_data.action:
    for fcurve in _get_fcurves(armature.animation_data.action):
        for kp in fcurve.keyframe_points:
            kp.interpolation = 'LINEAR' if IMPORTED_BONE_TRANSFORM_DATA else 'BEZIER'
            if not IMPORTED_BONE_TRANSFORM_DATA:
                kp.easing = 'AUTO'

print("   " + str(_bones_reset_ok) + " bones animados con animacion importada: " + {label_literal})

# Las mallas de ojos no pertenecen al Armature. El exportador las guarda en
# EYES_DATA y requieren acciones independientes sobre el objeto y sus shape keys.
_eyes_animated_ok = 0
for _eye_name, _eye_data in IMPORTED_EYES_DATA.items():
    _eye = bpy.data.objects.get(_eye_name)
    if not _eye or _eye.type != 'MESH':
        print("   ojo importado no encontrado: " + str(_eye_name))
        continue

    # Guardar el estado ajeno al clip. Crear keyframes cambia inmediatamente
    # los valores del datablock y deja el ultimo frame como estado base si no
    # se restaura de forma explicita.
    _eye_base_matrix = _eye.matrix_basis.copy()
    _eye_base_rotation_mode = _eye.rotation_mode
    _eye_base_hide_viewport = False
    _eye_base_hide_render = False
    _eye_base_shape_values = {{}}
    if getattr(_eye.data, "shape_keys", None):
        _eye_base_shape_values = {{
            _key.name: 0.0 for _key in _eye.data.shape_keys.key_blocks
        }}

    # La importacion nunca anima hide_viewport/hide_render. El parpadeo se
    # reproduce con el shape key Closed; ocultar el objeto mediante una pista
    # booleana puede filtrarse fuera del strip en ciertas combinaciones NLA.
    _eye.hide_viewport = False
    _eye.hide_render = False
    _object_channels = ("location", "rotation_quaternion", "rotation_euler", "scale")
    _has_object_keys = any(_eye_data.get(_channel) for _channel in _object_channels)
    if _has_object_keys:
        if not _eye.animation_data:
            _eye.animation_data_create()
        _eye_action_name = f"slot_{{SLOT_INDEX:03d}}_cerdo_1_eye_obj_{{_eye_name}}"
        _old_eye_action = bpy.data.actions.get(_eye_action_name)
        if _old_eye_action:
            bpy.data.actions.remove(_old_eye_action, do_unlink=True)
        _eye_action = bpy.data.actions.new(name=_eye_action_name)
        _eye.animation_data.action = _eye_action
        if _eye_data.get("rotation_quaternion"):
            _eye.rotation_mode = 'QUATERNION'

        for _channel in _object_channels:
            for _rel_frame, _value in _eye_data.get(_channel, {{}}).items():
                _frame = start_frame + int(_rel_frame)
                setattr(_eye, _channel, _value)
                _eye.keyframe_insert(data_path=_channel, frame=_frame)

        for _fc in _get_fcurves(_eye.animation_data):
            for _kp in _fc.keyframe_points:
                _kp.interpolation = 'BEZIER'
        _eye_done = _eye.animation_data.action
        _eye.animation_data.action = None
        _eye_track = _eye.animation_data.nla_tracks.new()
        _eye_track.name = f"Slot_{{SLOT_INDEX:03d}}_eye_object_{{_eye_name}}"
        _eye_strip = _eye_track.strips.new(_eye_done.name, start_frame, _eye_done)
        _eye_strip.frame_end = end_frame
        # Los extremos del export son la transformacion neutral correcta del
        # ojo. HOLD evita que Blender vuelva a la escala interna (1,1,1) en los
        # tramos vecinos; las expresiones siguen aisladas en otro strip NOTHING.
        _eye_strip.extrapolation = 'HOLD'
        _eye_strip.blend_type = 'REPLACE'
        _eye_strip.influence = 1.0

    _shape_data = _eye_data.get("shape_keys", {{}})
    if _shape_data:
        if not _eye.data.shape_keys:
            _eye.shape_key_add(name="Basis", from_mix=False)

        # Los exports fidelity_v3 incluyen las coordenadas exactas de cada
        # shape key. Restaurarlas evita reconstrucciones aproximadas y mantiene
        # identica la expresion creada originalmente.
        _exact_geometry = IMPORTED_EYE_SHAPE_GEOMETRY.get(_eye_name, {{}})
        for _geometry_name, _coordinates in _exact_geometry.items():
            _geometry_key = _eye.data.shape_keys.key_blocks.get(_geometry_name)
            if _geometry_key is None:
                _geometry_key = _eye.shape_key_add(name=_geometry_name, from_mix=False)
            if len(_geometry_key.data) != len(_coordinates):
                print("   topologia incompatible para shape key: " + _eye_name + "/" + _geometry_name)
                continue
            for _index, _coordinate in enumerate(_coordinates):
                _geometry_key.data[_index].co = _coordinate

        # El .py exportado guarda curvas y valores, pero versiones anteriores
        # no guardaban la geometria de cada expresion. Si el blend receptor aun
        # no tiene esos shape keys, reconstruir el juego global usando la misma
        # configuracion visible del Sistema de Ojos del addon.
        _required_bases = {{
            _name.split("__", 1)[0] for _name in _shape_data.keys()
            if _name.split("__", 1)[0] != "Closed"
        }}
        _import_suffix = "__import006"
        _geometry_bases = {{_name.split("__", 1)[0] for _name in _exact_geometry.keys()}}
        _bases_to_rebuild = _required_bases - _geometry_bases
        if _bases_to_rebuild:
            try:
                import sys as _sys
                import types as _types
                _eye_system_module = next(
                    (_module for _name, _module in _sys.modules.items()
                     if _name.endswith(".eye_system") and hasattr(_module, "build_expression_shape_keys")),
                    None,
                )
                if _eye_system_module is None:
                    try:
                        import importlib as _importlib
                        _eye_system_module = _importlib.import_module("cerdo_1_animation_studio.eye_system")
                    except Exception:
                        _eye_system_module = None
                _studio = getattr(bpy.context.scene, "cerdo_1_st", None)
                _source_eye_settings = getattr(_studio, "eye_expr", None)
                # Una importacion usa siempre intensidad geometrica 0.06. Se
                # conservan las demas opciones del panel sin modificarlo.
                _eye_settings = _types.SimpleNamespace(
                    subdivide_cuts=getattr(_source_eye_settings, "subdivide_cuts", 3),
                    affect_zone=getattr(_source_eye_settings, "affect_zone", "UPPER"),
                    invert_vertical=getattr(_source_eye_settings, "invert_vertical", True),
                    invert_horizontal=getattr(_source_eye_settings, "invert_horizontal", False),
                    swap_axes=getattr(_source_eye_settings, "swap_axes", False),
                    curve_mode=getattr(_source_eye_settings, "curve_mode", "QUADRATIC"),
                    intensity_feliz=0.06,
                    intensity_triste=0.06,
                    intensity_enojado=0.06,
                    intensity_sospecha=0.06,
                )
                if _eye_system_module:
                    _eye_system_module.build_expression_shape_keys(
                        _eye,
                        _eye_settings,
                        is_right_eye=(_eye_name == "ojo_derecho_cerdo_1"),
                        name_suffix=_import_suffix,
                    )
                    print("   shape keys importados a intensidad 0.06 para: " + _eye_name)
            except Exception as _eye_shape_error:
                print("   no se pudieron reconstruir shape keys en " + _eye_name + ": " + str(_eye_shape_error))

        # Respaldo autocontenido para clips antiguos: si el addon receptor no
        # esta importable, crear las expresiones basicas sobre la geometria del
        # ojo. Asi el archivo sigue reproduciendo visualmente EYES_DATA.
        _missing_bases = {{
            _base_name for _base_name in _bases_to_rebuild
            if _eye.data.shape_keys.key_blocks.get(_base_name + _import_suffix) is None
        }}
        if _missing_bases:
            _basis = _eye.data.shape_keys.key_blocks.get("Basis")
            _coords = [_point.co.copy() for _point in _basis.data]
            _axis_values = {{
                "x": [_co.x for _co in _coords],
                "y": [_co.y for _co in _coords],
                "z": [_co.z for _co in _coords],
            }}
            _ranges = {{_axis: max(_vals) - min(_vals) for _axis, _vals in _axis_values.items()}}
            _depth_axis = min(_ranges, key=_ranges.get)
            _vertical_axis = "z" if _depth_axis != "z" else min(
                (_axis for _axis in ("x", "y") if _axis != _depth_axis),
                key=lambda _axis: _ranges[_axis],
            )
            _horizontal_axis = next(
                _axis for _axis in ("x", "y", "z")
                if _axis not in (_depth_axis, _vertical_axis)
            )
            _v_min = min(_axis_values[_vertical_axis]); _v_max = max(_axis_values[_vertical_axis])
            _h_min = min(_axis_values[_horizontal_axis]); _h_max = max(_axis_values[_horizontal_axis])
            _v_center = (_v_min + _v_max) * 0.5; _h_center = (_h_min + _h_max) * 0.5
            _v_range = max(_v_max - _v_min, 1e-8); _h_range = max(_h_max - _h_min, 1e-8)
            _mirror = (_eye_name == "ojo_derecho_cerdo_1")

            for _base_name in sorted(_missing_bases):
                _expr = _base_name.lower()
                _new_key = _eye.shape_key_add(name=_base_name + _import_suffix, from_mix=False)
                _new_key.slider_min = -2.0; _new_key.slider_max = 2.0
                for _index, _orig in enumerate(_coords):
                    _v = getattr(_orig, _vertical_axis)
                    _h = getattr(_orig, _horizontal_axis)
                    _vf = (_v - _v_center) / (_v_range * 0.5)
                    if _vf <= 0.0:
                        continue
                    _hf = (_h - _h_center) / (_h_range * 0.5)
                    _hn = (_h - _h_min) / _h_range
                    if _mirror:
                        _hn = 1.0 - _hn
                    _offset = 0.0
                    if _expr == "feliz":
                        _offset = 0.06 * abs(_hf) ** 2 * _vf
                    elif _expr == "triste":
                        _offset = -0.06 * abs(_hf) ** 2 * _vf
                    elif _expr == "enojado":
                        _offset = (-0.06 * _hn + 0.03) * _vf
                    elif _expr == "sospecha":
                        _offset = (0.06 * _hn - 0.03) * _vf
                    elif _expr == "cerrado":
                        _offset = -(_v - _v_center) * 0.85
                    elif _expr == "cansado":
                        _offset = -(_v - _v_center) * 0.4 * _vf
                    elif _expr == "sorpresa":
                        _offset = (_v - _v_center) * 0.15 * _vf
                    _co = _orig.copy()
                    setattr(_co, _vertical_axis, _v + _offset)
                    _new_key.data[_index].co = _co
            print("   shape keys de respaldo creados para: " + _eye_name)

        _key_blocks = _eye.data.shape_keys.key_blocks

        def _resolve_eye_key(_source_name):
            _base_name = _source_name.split("__", 1)[0]
            if _source_name in _exact_geometry:
                _exact_geometry_key = _key_blocks.get(_source_name)
                if _exact_geometry_key:
                    return _exact_geometry_key
            _import_key = _key_blocks.get(_base_name + _import_suffix)
            if _import_key:
                return _import_key
            _exact = _key_blocks.get(_source_name)
            if _exact:
                return _exact
            _base_exact = _key_blocks.get(_base_name)
            if _base_exact:
                return _base_exact
            for _candidate in _key_blocks:
                if _candidate.name.split("__", 1)[0] == _base_name:
                    return _candidate
            if _base_name == "Closed":
                _closed = _eye.shape_key_add(name="Closed", from_mix=False)
                _min_z = min(_vertex.co.z for _vertex in _eye.data.vertices)
                for _index, _vertex in enumerate(_eye.data.vertices):
                    _co = _vertex.co.copy()
                    _co.z = _min_z
                    _closed.data[_index].co = _co
                return _closed
            print("   shape key importada no disponible en " + _eye_name + ": " + _source_name)
            return None

        _shape_keys_id = _eye.data.shape_keys
        if not _shape_keys_id.animation_data:
            _shape_keys_id.animation_data_create()
        _shape_action_name = f"slot_{{SLOT_INDEX:03d}}_cerdo_1_eye_shapes_{{_eye_name}}"
        _old_shape_action = bpy.data.actions.get(_shape_action_name)
        if _old_shape_action:
            bpy.data.actions.remove(_old_shape_action, do_unlink=True)
        _shape_action = bpy.data.actions.new(name=_shape_action_name)
        _shape_keys_id.animation_data.action = _shape_action

        _shape_count = 0
        for _source_name, _values in _shape_data.items():
            _target_key = _resolve_eye_key(_source_name)
            if not _target_key:
                continue
            for _rel_frame, _value in _values.items():
                _target_key.value = float(_value)
                _target_key.keyframe_insert(data_path="value", frame=start_frame + int(_rel_frame))
            _shape_count += 1

        if _shape_count and _shape_keys_id.animation_data.action:
            for _fc in _get_fcurves(_shape_keys_id.animation_data):
                for _kp in _fc.keyframe_points:
                    _kp.interpolation = 'BEZIER'
            _shape_done = _shape_keys_id.animation_data.action
            _shape_keys_id.animation_data.action = None
            _shape_track = _shape_keys_id.animation_data.nla_tracks.new()
            _shape_track.name = f"Slot_{{SLOT_INDEX:03d}}_eye_shapes_{{_eye_name}}"
            _shape_strip = _shape_track.strips.new(_shape_done.name, start_frame, _shape_done)
            _shape_strip.frame_end = end_frame
            _shape_strip.extrapolation = 'NOTHING'
            _shape_strip.blend_type = 'REPLACE'
            _shape_strip.influence = 1.0

    # Fuera del rango del strip debe evaluarse el estado que ya tenia el ojo,
    # nunca el ultimo valor escrito al construir la animacion importada.
    _eye.rotation_mode = _eye_base_rotation_mode
    _eye.matrix_basis = _eye_base_matrix
    # El cerdo_1.blend limpio puede traer los ojos con escala (1,1,1), aunque
    # su transform neutral real esta en el primer frame del clip exportado.
    # Usar ese primer valor como base mantiene las mallas colocadas y visibles
    # antes/despues; las variaciones de enfasis siguen limitadas al strip.
    if _eye_data.get("rotation_quaternion"):
        _eye.rotation_mode = 'QUATERNION'
    elif _eye_data.get("rotation_euler"):
        _eye.rotation_mode = 'XYZ'
    for _base_channel in ("location", "rotation_quaternion", "rotation_euler", "scale"):
        _base_values = _eye_data.get(_base_channel, {{}})
        if _base_values:
            _first_frame = min(_base_values.keys(), key=lambda _frame: int(_frame))
            setattr(_eye, _base_channel, _base_values[_first_frame])
    _eye.hide_viewport = _eye_base_hide_viewport
    _eye.hide_render = _eye_base_hide_render
    if getattr(_eye.data, "shape_keys", None):
        for _key in _eye.data.shape_keys.key_blocks:
            _key.value = _eye_base_shape_values.get(_key.name, 0.0)

    _eyes_animated_ok += 1

print("   " + str(_eyes_animated_ok) + " mallas de ojos animadas con EYES_DATA")
'''



# ============================================================
# HELPERS DE DIRECCIÓN - usados por los 3 generadores de slots
# ============================================================

def _compute_direction_angle(p0, p1):
    """
    Calcula el ángulo de orientación del personaje dado un vector de movimiento.
    Usa la misma lógica que slot_2: cardinal vs diagonal + corrección Blender.
    Retorna grados flotantes en [-180, 180].
    Si no hay componente horizontal retorna None.
    """
    import math as _math
    dx = p1['x'] - p0['x']
    dy = p1['y'] - p0['y']
    if dx == 0 and dy == 0:
        return None
    ang_raw = _math.degrees(_math.atan2(dx, dy))
    ang_rounded = round(ang_raw / 90.0) * 90.0
    ang_diff = abs(ang_raw - ang_rounded)
    if ang_diff < 45:
        ang = ang_rounded
    else:
        ang = -ang_raw
    while ang > 180:  ang -= 360
    while ang < -180: ang += 360
    # Corrección eje Y invertido Blender
    if   ang ==  90: ang = -90
    elif ang == -90: ang =  90
    return ang


def _smoothstep_val(x):
    """Función smoothstep S-curve: suave en extremos, máxima vel en centro."""
    if x <= 0: return 0.0
    if x >= 1: return 1.0
    return x * x * (3.0 - 2.0 * x)


def _angle_diff_shortest(target, current):
    """Diferencia angular más corta considerando la discontinuidad 360°."""
    d = target - current
    while d >  180: d -= 360
    while d < -180: d += 360
    return d


def generate_saltar_subir(slot_index, start_frame, points, today, root_rot=(0, 0, -90), fps=24.0):
    return _adaptive_jump.generate_jump(slot_index,start_frame,points,root_rot,'subir',fps,KEYFRAMES_SALTAR_SUBIR)


def generate_saltar_bajar(slot_index, start_frame, points, today, root_rot=(0, 0, -90), fps=24.0):
    return _adaptive_jump.generate_jump(slot_index,start_frame,points,root_rot,'bajar',fps,KEYFRAMES_SALTAR_BAJAR)


# ============================================================
# PARADA — NUEVO 2026-07-08
# ============================================================
#
# Pedido de Kebyn: el root se detiene por completo en una coordenada
# elegida por la IA (no por el usuario/historia — solo aplica en modo
# AUTO), para dejar un hueco donde SI tenga sentido animar una accion
# puntual (gesto, revision, reaccion) via el sistema de poses
# (CONCATENAR), en vez de forzarla sobre una caminata en curso.
#
# FRAMES_PARADA — CORRECCION 2026-07-09 (pedido de Kebyn: "no debe estar
# hardcodeado el numero de frames para cuando este parado"). Ya NO es una
# constante fija de modulo: generate_parada() ahora recibe `frames_parada`
# como parametro, configurable desde el panel del addon
# (context.scene.cerdo_1_path.frames_parada, ver CERDO_1PathSettings en
# path_recorder.py). FRAMES_PARADA_DEFAULT solo se usa si alguien llama a
# generate_parada() sin pasar frames_parada explicitamente (compatibilidad
# hacia atras / uso fuera del addon).
#
# Debe coincidir con self.frames_parada del lado del pipeline Python
# (cerdo_1_story_generator.py — derivado de n_poses_por_parada, tambien sin
# techo, ver ese archivo), o el timing calculado alli y lo que Blender
# reproduce aqui quedan desincronizados. Kebyn debe fijar
# context.scene.cerdo_1_path.frames_parada al mismo valor que resulte de
# n_poses_por_parada * (DURACION_MIN_POSE + MARGEN_VARIACION_POSE) en el
# pipeline (default historico: 3 * 20 = 60).
#
# A diferencia de saltar_subir/saltar_bajar (que aplican una animacion
# de bones ya capturada, KEYFRAME_DATA), una parada NO escribe ningun
# keyframe de rotacion sobre los bones del armature. Es intencional:
# el objetivo es dejar el armature exactamente como quedo al final del
# tramo anterior, sin tocarlo, para que el sistema de poses (CONCATENAR)
# tenga un lienzo libre donde superponer la action_pose asignada a este
# tramo por `_distribuir_poses_en_segmentos` en el pipeline. Lo unico
# que esta función SI fija es la posicion/orientacion del root (Empty
# "cerdo_1"), que se mantiene inmovil en el punto dado durante los
# frames_parada — igual que un salto fija el desplazamiento del root,
# pero aca sin desplazamiento.
FRAMES_PARADA_DEFAULT = 60
PARADA_FIX_VERSION = "2026-09-14-eye-neutral-transform-hold-v12"


def generate_parada(slot_index, start_frame, points, today, root_rot=(0, 0, -90),
                     frames_parada=None, anim_file_path=None):
    """Genera un slot de 'parada': root inmovil `frames_parada` frames, con
    los bones reseteados a su pose de rest (canvas realmente limpio para
    la action_pose que superponga CONCATENAR).

    `frames_parada`: sin limite — cualquier entero >= 1. Si no se pasa
    (None), usa FRAMES_PARADA_DEFAULT como fallback comodo, NO como techo.

    `anim_file_path`: NUEVO (Kebyn, 2026-09-13) — ruta a un script .py de
    animacion importada (ej. exportado por el conversor de Mixamo, mismo
    formato que slot_001_parado_discutiendo_dba2c3.py: modulo con un
    diccionario KEYFRAME_DATA de bone -> {frame: (rx, ry, rz)}). Si se
    pasa y el archivo es valido, esta parada reproduce esa animacion
    completa en vez de la pose estatica 'parado' (canvas limpio) de
    siempre — el root sigue inmovil (sigue siendo una 'parada': no
    camina), pero el cuerpo reproduce el clip importado. La duracion de
    este slot pasa a ser la del clip importado (se ignora `frames_parada`
    en ese caso, igual que ya hacen golpe_estomago_1/levantarse_1/
    conversar_1/etc. con sus propios TOTAL_FRAMES_* fijos). Si el archivo
    no existe o no se puede leer, se hace fallback silencioso (con
    mensaje en consola) al comportamiento de 'parada' de siempre.

    `points` debe ser una lista de 2 puntos IDENTICOS (misma x/y/z) —
    exactamente lo que produce `group_segments()` cuando
    `detect_movement_type` devuelve "parada".
    """
    _anim_kf_data = None
    _anim_eye_data = {}
    _anim_bone_transform_data = {}
    _anim_eye_geometry = {}
    _anim_frame_count = None
    if anim_file_path:
        (_anim_kf_data, _anim_eye_data, _anim_bone_transform_data,
         _anim_eye_geometry, _anim_frame_count) = _load_animation_data_from_anim_file(anim_file_path)

    if _anim_kf_data and _anim_frame_count:
        total_frames = _anim_frame_count
    else:
        total_frames = frames_parada if frames_parada is not None else FRAMES_PARADA_DEFAULT
    end_frame = start_frame + total_frames - 1
    p0 = points[0]['coordinates']
    p1 = points[1]['coordinates']
    traj = _fmt_trajectory(points)
    rx, ry, rz = root_rot

    if _anim_kf_data:
        import os as _os_mod_gp
        _anim_src_label = _os_mod_gp.path.basename(anim_file_path)
        _bones_animated_count = len(_anim_kf_data)
        _eyes_animated_count = len(_anim_eye_data)
        _movement_type_label = "parada_animada"
        _animation_type_label = "imported_animation"
        _bones_block = _build_parada_anim_importada_block(
            _anim_kf_data, start_frame, slot_index, _anim_src_label)
        _estado_final_line = (
            'print("PARADA APLICADA — animacion importada reproducida (root inmovil): " + '
            + repr(_anim_src_label) + ')'
        )
    else:
        _bones_animated_count = 14
        _movement_type_label = "parada"
        _animation_type_label = "stop_hold_reset"
        _bones_block = _build_parada_pose_estatica_block(slot_index)
        _estado_final_line = (
            'print("PARADA APLICADA — root inmovil, bones en postura \'parado\' (canvas limpio para pose)")'
        )

    # _bones_block se embebe dentro del cuerpo de execute_animation()
    # (indentado a 4 espacios en el slot generado) -- ambos builders
    # devuelven texto SIN indentar (columna 0), asi que se indenta aca
    # uniformemente antes de insertarlo en el template de mas abajo. Las
    # lineas dentro de listas/dicts multilinea (ej. _PARADO_POSE = {{...}})
    # no dependen de una indentacion exacta (Python la ignora dentro de
    # parentesis/corchetes/llaves abiertos), asi que sumarles 4 espacios
    # tambien no rompe nada -- solo importa para las lineas que SI son
    # sentencias propias (if/for/asignaciones de primer nivel).
    _bones_block = "\n".join(
        ("    " + _ln if _ln.strip() else _ln) for _ln in _bones_block.split("\n")
    )

    if _anim_kf_data:
        _docstring_nota = (
            f'NOTA: este slot mantiene el root inmovil y reproduce la animacion\n'
            f'importada "{_anim_src_label}" ({_bones_animated_count} huesos,\n'
            f'{_eyes_animated_count} mallas de ojos, {total_frames} frames) en vez de\n'
            f'la pose estatica "parado" -- ver\n'
            f'anim_file_path en generate_parada() / parada_anim_file en\n'
            f'CERDO_1PathPoint (path_recorder.py).'
        )
    else:
        _docstring_nota = (
            'NOTA: este slot mantiene el root inmovil y fuerza todos los bones\n'
            'animables a la postura base "parado" (Kebyn, parado.json) durante todo\n'
            'el rango — canvas limpio (brazos caidos a los costados, no T-pose) para\n'
            'que CONCATENAR superponga la action_pose asignada a este tramo, sin\n'
            'heredar la ultima pose congelada del segmento anterior.'
        )

    code = f'''# -*- coding: utf-8 -*-
"""
slot_{slot_index:03d}_parada.py
Cerdo_1 - Slot {slot_index}

GENERADO AUTOMATICAMENTE
Fecha de generacion: {today}

{_docstring_nota}
"""

import bpy
import math

# --- Compatibilidad Action.fcurves (eliminado en Blender 5.0+, ver slots/channelbags) ---
def _get_fcurves(target):
    anim_data = None
    action = target
    if isinstance(target, bpy.types.AnimData):
        anim_data = target
        action = anim_data.action
    if action is None:
        return []
    if hasattr(action, 'fcurves'):
        return action.fcurves
    from bpy_extras import anim_utils as _au
    slot = anim_data.action_slot if anim_data is not None else None
    if slot is None and action.slots:
        slot = action.slots[0]
    if slot is None:
        return []
    channelbag = _au.action_ensure_channelbag_for_slot(action, slot)
    return channelbag.fcurves if channelbag else []

# ============================================
# CONFIGURACION DEL SLOT
# ============================================

SLOT_INDEX = {slot_index}
START_FRAME = {start_frame}
END_FRAME = {end_frame}  # {start_frame} + {total_frames} - 1
TOTAL_FRAMES = {total_frames}

# ============================================
# DATOS DE TRAYECTORIA EMBEBIDOS - SLOT {slot_index}
# ============================================

{traj}

# ============================================
# FIN DE CONFIGURACION DEL SLOT {slot_index}
# ============================================

ANIMATION_INFO = {{
    'name': 'slot_{slot_index:03d}_parada.py',
    'frame_count': {total_frames},
    'fps': 24,
    'duration_seconds': {total_frames/24:.2f},
    'entity': 'Cerdo_1',
    'slot': {slot_index},
    'movement_type': '{_movement_type_label}',
    'narrative_importance': 'expression',
    'rig_type': 'full_armature',
    'source': 'cerdo_1_rig',
    'bones_animated': {_bones_animated_count},
    'animation_type': '{_animation_type_label}',
}}

# Root Location: se mantiene fijo — punto {points[0]['index']} == punto {points[1]['index']}
# ({p0['x']}, {p0['y']}, {p0['z']})

ROOT_LOCATION_DATA = {{
    {start_frame}: ({p0['x']}, {p0['y']}, {p0['z']}),
    {end_frame}: ({p1['x']}, {p1['y']}, {p1['z']}),
}}

ROOT_ROTATION_X = {rx}
ROOT_ROTATION_Y = {ry}
ROOT_ROTATION_Z = {rz}   # sin trayecto (parada) -> se usa la orientacion base, fija

ROOT_ROTATION_DATA = {{
    {start_frame}: (math.radians({rx}), math.radians({ry}), math.radians({rz})),
    {end_frame}:   (math.radians({rx}), math.radians({ry}), math.radians({rz})),
}}

# Animacion independiente de las mallas de ojos del archivo importado.
# Los frames permanecen relativos (0-based) y execute_animation los desplaza
# a START_FRAME, igual que hace el bloque de bones al generar KEYFRAME_DATA.
IMPORTED_EYES_DATA = {repr(_anim_eye_data)}
IMPORTED_BONE_TRANSFORM_DATA = {repr(_anim_bone_transform_data)}
IMPORTED_EYE_SHAPE_GEOMETRY = {repr(_anim_eye_geometry)}


def execute_animation(player_parts, start_frame=None, end_frame=None):
    """
    Slot {slot_index}: 'Parada' de Cerdo_1 — root inmovil, bones forzados
    a la postura "parado" (brazos caidos a los costados) — canvas limpio
    para la action_pose superpuesta por CONCATENAR.

    FIX (Kebyn, 2026-07-11): antes este slot NO tocaba los bones en
    absoluto ("sin keyframes de bones"), asumiendo que eso dejaba un
    "canvas libre". En la practica, Blender NO resetea los pose bones a
    su rest pose solo porque ningun NLA strip los este animando en ese
    rango — el pose bone simplemente conserva el ULTIMO valor evaluado
    del segmento anterior (ej. una pose de caminata a medio paso,
    congelada). Eso se veia como "una animacion por defecto" que
    bloqueaba visualmente la pose que CONCATENAR queria inyectar. Se creo
    entonces una accion de armature dedicada que fuerza TODOS los bones
    animables a rotacion 0,0,0 — su rest pose — durante los frames de
    esta parada.

    FIX 2 (Kebyn, 2026-08-02): ese reset a (0,0,0) puro resulto ser la
    T-pose real del rig (rest bind con los brazos estirados
    horizontalmente hacia los costados), visible cada vez que Cerdo_1 se
    quedaba parado. Se reemplaza por _PARADO_POSE (ver parado.json): los
    brazos superiores rotan 90 grados en X para caer a los costados; el
    resto de los huesos se mantiene en (0,0,0) igual que antes.
    """
    start_frame = START_FRAME
    end_frame = END_FRAME

    armature = bpy.data.objects.get("pig.arma_cerdo_1")
    if not armature or armature.type != 'ARMATURE':
        print("Error: No se encontró el Armature")
        return False

    cerdo_1_root = next((o for o in bpy.data.objects if o.name == 'cerdo_1' and o.type == 'EMPTY'), None)

    # ============================================
    # SETUP DE ACCION NLA DEDICADA — BONES
    # (postura estatica 'parado' de siempre, O animacion .py importada
    # para este punto -- ver anim_file_path / _bones_block mas arriba en
    # generate_parada())
    # ============================================
{_bones_block}

    # ============================================
    # SETUP DE ACCION NLA DEDICADA — SOLO ROOT
    # ============================================
    _root_action_name = f'slot_{slot_index:03d}_cerdo_1_parada_root'

    if cerdo_1_root:
        if not cerdo_1_root.animation_data:
            cerdo_1_root.animation_data_create()
        _root_existing = bpy.data.actions.get(_root_action_name)
        if _root_existing:
            bpy.data.actions.remove(_root_existing)
        _root_action = bpy.data.actions.new(name=_root_action_name)
        cerdo_1_root.animation_data.action = _root_action

        for frame, rotation in ROOT_ROTATION_DATA.items():
            cerdo_1_root.rotation_euler = rotation
            cerdo_1_root.keyframe_insert(data_path="rotation_euler", frame=frame)
        for frame, location in ROOT_LOCATION_DATA.items():
            cerdo_1_root.location = location
            cerdo_1_root.keyframe_insert(data_path="location", frame=frame)

        if cerdo_1_root.animation_data.action:
            for fcurve in _get_fcurves(cerdo_1_root.animation_data.action):
                for kp in fcurve.keyframe_points:
                    kp.interpolation = 'CONSTANT'   # sin interpolacion: es un hold, no una transicion

    {_estado_final_line}
    print(f"  [PARADA_FIX_VERSION] {PARADA_FIX_VERSION}")
    print(f"  Frames: {{start_frame}}-{{end_frame}}")

    # ============================================
    # EMPUJAR ACCIONES AL NLA
    # ============================================
    if armature.animation_data and armature.animation_data.action:
        _arm_done  = armature.animation_data.action
        armature.animation_data.action = None
        _arm_track = armature.animation_data.nla_tracks.new()
        _arm_track.name = f'Slot_{slot_index:03d}_arm'
        _arm_strip = _arm_track.strips.new(_arm_done.name, start_frame, _arm_done)
        _arm_strip.frame_end      = end_frame
        _arm_strip.extrapolation  = 'NOTHING'
        _arm_strip.use_auto_blend = False
        _arm_strip.blend_in       = 0
        _arm_strip.blend_out      = 0

    if cerdo_1_root and cerdo_1_root.animation_data and cerdo_1_root.animation_data.action:
        _root_done  = cerdo_1_root.animation_data.action
        cerdo_1_root.animation_data.action = None
        _root_track = cerdo_1_root.animation_data.nla_tracks.new()
        _root_track.name = f'Slot_{slot_index:03d}_root'
        _root_strip = _root_track.strips.new(_root_done.name, start_frame, _root_done)
        _root_strip.frame_end      = end_frame
        _root_strip.extrapolation  = 'HOLD_FORWARD'
        _root_strip.use_auto_blend = False
        _root_strip.blend_in       = 0
        _root_strip.blend_out      = 0

    # El clip importado ya contiene sus parpadeos y expresiones completas.
    # No escribir encima el parpadeo generico de una parada estatica.
    if IMPORTED_EYES_DATA:
        return True

    # ============================================
    # SETUP SHAPE KEYS DE PARPADEO
    # (igual que en los demas tipos de slot — un parpadeo natural
    # durante la parada no rompe nada, y la sensacion de "vivo" ayuda
    # justo en un momento donde el personaje esta quieto)
    # ============================================
    def _create_curtain_effect(eye_obj, shape_key):
        mesh = eye_obj.data
        min_z = min(v.co.z for v in mesh.vertices)
        for i, vert in enumerate(mesh.vertices):
            new_co = vert.co.copy()
            new_co.z = min_z
            shape_key.data[i].co = new_co

    def setup_blink_shape_keys():
        for obj_name in ["ojo_izquierdo_cerdo_1", "ojo_derecho_cerdo_1"]:
            eye_obj = bpy.data.objects.get(obj_name)
            if not eye_obj or eye_obj.type != "MESH":
                print(f"   setup_blink: WARNING '{{obj_name}}' no encontrado")
                continue
            if not eye_obj.data.shape_keys:
                eye_obj.shape_key_add(name="Basis", from_mix=False)
            existing = [sk.name for sk in eye_obj.data.shape_keys.key_blocks]
            if "Closed" not in existing:
                closed_key = eye_obj.shape_key_add(name="Closed", from_mix=False)
                _create_curtain_effect(eye_obj, closed_key)
                print(f"   setup_blink: 'Closed' creado en '{{obj_name}}'")
            else:
                print(f"   setup_blink: 'Closed' ya existe en '{{obj_name}}' -- OK")
    setup_blink_shape_keys()

    blink_start = start_frame + int((end_frame - start_frame + 1) * 0.50)
    blink_seq = {{
        1: {{"closed": 0.0,  "hide": False}},
        2: {{"closed": 0.25, "hide": False}},
        3: {{"closed": 0.5,  "hide": False}},
        4: {{"closed": 0.75, "hide": False}},
        5: {{"closed": 1.0,  "hide": True}},
        6: {{"closed": 1.0,  "hide": True}},
        7: {{"closed": 0.75, "hide": False}},
        8: {{"closed": 0.5,  "hide": False}},
        9: {{"closed": 0.25, "hide": False}},
    }}
    for t in range(start_frame, end_frame + 1):
        blink_applied = False
        if blink_start <= t < blink_start + 9:
            blink_applied = True
            offset = t - blink_start + 1
            frame_data = blink_seq.get(offset, {{"closed": 0.0, "hide": False}})
            progress  = frame_data["closed"]
            hide_eye  = frame_data["hide"]
        if blink_applied:
            for eye_name in ["ojo_izquierdo_cerdo_1", "ojo_derecho_cerdo_1"]:
                eye = bpy.data.objects.get(eye_name)
                if eye and hasattr(eye.data, 'shape_keys') and eye.data.shape_keys:
                    ck = eye.data.shape_keys.key_blocks.get("Closed")
                    if ck:
                        ck.value = progress
                        ck.keyframe_insert(data_path='value', frame=t)
                        eye.hide_viewport = hide_eye
                        eye.hide_render   = hide_eye
                        eye.keyframe_insert(data_path="hide_viewport", frame=t)
                        eye.keyframe_insert(data_path="hide_render",   frame=t)
        else:
            for eye_name in ["ojo_izquierdo_cerdo_1", "ojo_derecho_cerdo_1"]:
                eye = bpy.data.objects.get(eye_name)
                if eye and hasattr(eye.data, 'shape_keys') and eye.data.shape_keys:
                    ck = eye.data.shape_keys.key_blocks.get("Closed")
                    if ck:
                        ck.value = 0.0
                        ck.keyframe_insert(data_path='value', frame=t)
                        eye.hide_viewport = False
                        eye.hide_render   = False
                        eye.keyframe_insert(data_path="hide_viewport", frame=t)
                        eye.keyframe_insert(data_path="hide_render",   frame=t)

    return True


if __name__ == "__main__":
    execute_animation(None, start_frame=START_FRAME, end_frame=END_FRAME)
'''
    return code, end_frame


# ============================================================
# ESTILOS DE CAMINATA (multiplexor) — Kebyn, 2026-08-01
# ============================================================
# Cada estilo redefine, a partir del ciclo NORMAL calibrado con slot_001:
#   - speed_mult  : multiplica FRAMES_PER_UNIT (frames por unidad de
#                   distancia). >1 = Cerdo_1 tarda MAS frames en recorrer
#                   la misma distancia (mas lento). <1 = menos frames
#                   (mas rapido).
#   - cycle_mult  : multiplica FRAMES_PER_BIO_CYCLE (duracion de un ciclo
#                   de piernas/brazos completo). >1 = zancada mas lenta
#                   (menos pasos por segundo). <1 = cadencia mas rapida.
#   - range_mult  : multiplicadores sobre las mismas 'ranges' (en grados,
#                   antes de math.radians) que ya usaba generate_caminar,
#                   mas 'knee_flex' que ANTES se calculaba pero nunca se
#                   aplicaba a Leg:BL:Bend_cerdo_1/Leg:BR:Bend_cerdo_1 (bug de
#                   huesos sin usar detectado al revisar cerdo_1_bones.json:
#                   la armadura trae 22 huesos, incluidas las rodillas,
#                   pero el ciclo de caminar solo animaba cadera+brazos).
#                   Ahora knee_flex SI se usa (ver calculate_knee_flex).
#   - lean_forward: inclinacion CONSTANTE hacia adelante de la columna
#                   (radianes), sumada al balanceo oscilante existente.
#   - vertical_bob: amplitud (metros) del rebote vertical del root en
#                   cada apoyo de pie -- antes el root solo se movia en
#                   linea recta sobre el plano de la trayectoria.
#   - asym_right_leg: 0.0-1.0 -- cuanto se debilita la pierna DERECHA
#                   (swing + flexion de rodilla) para simular cojera.
#                   Solo HERIDO lo usa; el resto va en 0.0 (simetrico).
WALK_STYLE_PARAMS = {
    'NORMAL': {
        'label': 'Caminar Normal',
        'speed_mult': 1.0, 'cycle_mult': 1.0,
        'range_mult': {
            'arm_swing_y': 1.0, 'elbow_flex': 1.0, 'leg_swing_x': 1.0,
            'knee_flex': 1.0, 'spine_bend': 1.0, 'neck_tilt': 1.0,
            'neck_nod': 1.0, 'arm_base_x': 1.0,
        },
        'lean_forward': 0.0, 'vertical_bob': 0.0, 'asym_right_leg': 0.0,
    },
    'LENTO': {
        'label': 'Caminar Lento',
        'speed_mult': 1.35, 'cycle_mult': 1.25,
        'range_mult': {
            'arm_swing_y': 0.6, 'elbow_flex': 0.8, 'leg_swing_x': 0.65,
            'knee_flex': 0.85, 'spine_bend': 0.7, 'neck_tilt': 0.7,
            'neck_nod': 0.6, 'arm_base_x': 1.0,
        },
        'lean_forward': 0.0, 'vertical_bob': 0.0, 'asym_right_leg': 0.0,
    },
    'HERIDO': {
        'label': 'Caminar Herido',
        'speed_mult': 1.6, 'cycle_mult': 1.4,
        'range_mult': {
            # brazo/codo un poco mas rigidos (uno protege la herida)
            'arm_swing_y': 0.5, 'elbow_flex': 0.6, 'leg_swing_x': 0.55,
            'knee_flex': 0.5, 'spine_bend': 1.3, 'neck_tilt': 0.8,
            'neck_nod': 0.5, 'arm_base_x': 1.1,
        },
        'lean_forward': 0.035, 'vertical_bob': 0.045, 'asym_right_leg': 0.55,
    },
    'RAPIDO': {
        'label': 'Caminar Rapido',
        'speed_mult': 0.75, 'cycle_mult': 0.8,
        'range_mult': {
            'arm_swing_y': 1.25, 'elbow_flex': 1.15, 'leg_swing_x': 1.2,
            'knee_flex': 1.15, 'spine_bend': 1.15, 'neck_tilt': 1.1,
            'neck_nod': 1.1, 'arm_base_x': 1.0,
        },
        'lean_forward': 0.05, 'vertical_bob': 0.012, 'asym_right_leg': 0.0,
    },
    'CORRER': {
        'label': 'Correr',
        'speed_mult': 0.5, 'cycle_mult': 0.55,
        'range_mult': {
            'arm_swing_y': 1.6, 'elbow_flex': 1.7, 'leg_swing_x': 1.7,
            'knee_flex': 1.8, 'spine_bend': 1.8, 'neck_tilt': 0.6,
            'neck_nod': 1.2, 'arm_base_x': 0.85,
        },
        'lean_forward': 0.12, 'vertical_bob': 0.06, 'asym_right_leg': 0.0,
    },
}


# RESTAURADO (Kebyn): el tercer tramo "vuelta a POSE_PARADO" (frames
# 16..15+RETURN_TO_PARADO_FRAMES) esta de vuelta, a pedido de Kebyn. La
# revision anterior lo habia quitado y en su lugar agregaba una cola de
# transicion hacia la pose de caminata (TRANSITION_TO_WALK_FRAMES), para
# evitar un salto visible en piernas/brazos justo donde colocar_antorcha
# empalmaba con el walk cycle siguiente. Esa cola de transicion se
# elimina aca: el slot vuelve a terminar de pie, EN LA MISMA POSE Y EN LA
# MISMA COORDENADA (points[0]) en la que arranco -- el root nunca se
# desplaza durante colocar_antorcha (ver ROOT_LOCATION_DATA en
# generate_colocar_antorcha()). El tramo "caminar" que group_segments()
# inyecta automaticamente justo despues (mismos 2 puntos points[0]/
# points[1]) es quien hace caminar de verdad al personaje, arrancando
# tambien desde points[0] -- exactamente el punto donde termina este
# slot, sin ningun salto de posicion.
#
# NOTA: como antes, esto reintroduce el corte que la cola de transicion
# buscaba evitar -- el walk cycle de generate_caminar() no arranca en una
# pose neutral en su frame 0, sino en una pose de zancada a mitad de
# camino segun el estilo de caminata del tramo. Con este cambio, Cerdo_1
# vuelve a pararse derecho al final de colocar_antorcha y el frame
# siguiente (ya del tramo "caminar") puede iniciar de golpe en esa pose
# de zancada -- posible salto visible en piernas/brazos en ese limite.
# Se deja asi porque es lo pedido explicitamente; si en el futuro hace
# falta suavizar ese empalme, _walk_pose_at_phase0() (mas abajo, ya no
# usada aca) todavia sirve como base para reconstruir una cola de
# transicion equivalente.
RETURN_TO_PARADO_FRAMES = 14
TOTAL_FRAMES_COLOCAR_ANTORCHA = 16 + RETURN_TO_PARADO_FRAMES  # 30

# Frame LOCAL (relativo al inicio del slot, 0-based) en el que el
# personaje esta EXACTAMENTE en la pose de inclinado_colocando_antorcha.json
# -- ver KEYFRAMES_COLOCAR_ANTORCHA mas abajo. Es tambien el frame en el que
# la antorcha debe aparecer (ver TORCH_APPEAR_FRAME en generate_colocar_antorcha()
# y su uso en operators_segments.py/path_recorder.py): antes de este frame la
# antorcha esta oculta, nunca aparece a mitad de camino ni por una trayectoria
# de lanzamiento -- 'aparece' de golpe justo cuando el cuerpo llega a esa pose.
# RESTAURADO (Kebyn): ya NO es el ultimo frame del slot -- a partir de aca
# arranca de nuevo el tramo de vuelta a POSE_PARADO (ver
# RETURN_TO_PARADO_FRAMES arriba).
MID_FRAME_COLOCAR_ANTORCHA = 15

# NUEVO (Kebyn, 2026-08-22): mismas constantes, misma arquitectura de 3
# tramos (parado->agachado->parado), para "colocar_mesa_de_crafteo" --
# ver KEYFRAMES_COLOCAR_MESA_CRAFTEO mas arriba. TABLE_APPEAR_FRAME
# (generate_colocar_mesa_crafteo()) usa MID_FRAME_COLOCAR_MESA_CRAFTEO
# igual que TORCH_APPEAR_FRAME usa MID_FRAME_COLOCAR_ANTORCHA.
TOTAL_FRAMES_COLOCAR_MESA_CRAFTEO = 16 + RETURN_TO_PARADO_FRAMES  # 30
MID_FRAME_COLOCAR_MESA_CRAFTEO = 15

# NUEVO (Kebyn, "crear pared NxN bloques"): cantidad de frames de UN solo
# ciclo agachar->colocar->parar (el mismo ciclo completo de
# "colocar_mesa_de_crafteo", ver _build_crear_pared_nxn_keyframes() mas
# abajo) -- se repite una vez por cada bloque de la grilla Filas x
# Columnas, sin superponerse (bloque 2 arranca justo donde termina el
# bloque 1, ya de pie). calcular_estimacion_geometrica() (path_recorder.py)
# importa esta constante para calcular la duracion total del slot
# (FRAMES_PER_BLOQUE_PARED_NXN * filas * columnas) sin tener que duplicar
# el numero 30 a mano.
FRAMES_PER_BLOQUE_PARED_NXN = TOTAL_FRAMES_COLOCAR_MESA_CRAFTEO

# NUEVO (Kebyn, "elegir cuantos frames dura toda la animacion de crear
# pared"): piso minimo de frames por bloque cuando Kebyn elige un total
# de frames a mano (ver resolve_pared_nxn_timing() mas abajo) -- por
# debajo de esto la pose de agacharse/colocar queda irreconocible
# (demasiado poco tiempo para leerse).
MIN_FRAMES_PER_BLOQUE_PARED_NXN = 6


def resolve_pared_nxn_timing(num_bloques, pared_total_frames=0):
    """Decide cuantos frames dura el ciclo agachar->colocar->parar de
    CADA bloque de la grilla 'crear pared NxN', y en que frame relativo
    (dentro de ese ciclo) el cuerpo queda agachado colocando el bloque
    (para WALL_APPEAR_FRAME/appear_frame) -- fuente unica de verdad
    usada tanto por calcular_estimacion_geometrica() (path_recorder.py,
    Paso 1) como por generate_crear_pared_nxn() de aca abajo, para que
    la estimacion mostrada a Kebyn y la animacion real generada
    coincidan siempre exactamente.

    Si pared_total_frames es 0 (default, "automatico"): usa el ciclo
    fijo FRAMES_PER_BLOQUE_PARED_NXN de siempre, sin reescalar nada
    (comportamiento identico al de antes de este cambio).

    Si Kebyn elige un total de frames para TODA la animacion de crear
    pared (todos los bloques de la grilla, de principio a fin, campo
    "Frames totales" del punto en el Paso 1): ese total se reparte en
    partes iguales entre num_bloques bloques (frames_per_bloque =
    round(pared_total_frames / num_bloques), nunca menos que
    MIN_FRAMES_PER_BLOQUE_PARED_NXN), y el ciclo base de
    _build_colocar_mesa_crafteo_keyframes() se reescala en tiempo real
    a esa duracion (ver _resample_bone_cycle() mas abajo) -- mismo
    principio que el reescalado manual de KEYFRAMES_SALTAR_SUBIR
    (25->18 frames), pero calculado en caliente porque aca la duracion
    la elige Kebyn por recorrido, no es una constante fija del addon.

    El total real devuelto (frames_per_bloque * num_bloques) puede
    diferir un poco del pedido por Kebyn por el redondeo a frames
    enteros por bloque -- se devuelve ese total real para que
    UI/generador muestren siempre el mismo numero.

    Devuelve (frames_per_bloque, mid_rel, total_frames_real).
    """
    num_bloques = max(1, int(num_bloques))
    pared_total_frames = int(pared_total_frames or 0)
    if pared_total_frames <= 0:
        frames_per_bloque = FRAMES_PER_BLOQUE_PARED_NXN
    else:
        frames_per_bloque = max(
            MIN_FRAMES_PER_BLOQUE_PARED_NXN,
            round(pared_total_frames / num_bloques),
        )
    mid_rel = round(
        (frames_per_bloque - 1) * MID_FRAME_COLOCAR_MESA_CRAFTEO
        / (TOTAL_FRAMES_COLOCAR_MESA_CRAFTEO - 1)
    )
    total_frames_real = frames_per_bloque * num_bloques
    return frames_per_bloque, mid_rel, total_frames_real


def _resample_bone_cycle(cycle, orig_len, new_len):
    """Reescala un ciclo denso {bone: {frame: (x,y,z)}} de orig_len
    frames (0..orig_len-1) a new_len frames (0..new_len-1), via
    interpolacion lineal por-componente sobre la posicion continua
    equivalente en la linea de tiempo original. Mismo principio que el
    reescalado manual de KEYFRAMES_SALTAR_SUBIR (25 muestras -> 18
    muestras, factor 24/17), pero calculado en tiempo real (no una
    tabla fija) para que Kebyn pueda elegir la duracion de 'crear pared
    NxN' por recorrido -- ver resolve_pared_nxn_timing(). Preserva
    siempre la pose exacta del primer y del ultimo frame del ciclo."""
    if new_len == orig_len:
        return cycle
    if new_len <= 1:
        return {bone: {0: frames[0]} for bone, frames in cycle.items()}
    result = {}
    scale = (orig_len - 1) / (new_len - 1)
    for bone, frames in cycle.items():
        bone_frames = {}
        for nf in range(new_len):
            pos = nf * scale
            f0 = int(math.floor(pos))
            f1 = min(f0 + 1, orig_len - 1)
            tt = pos - f0
            v0 = frames[f0]
            v1 = frames[f1]
            bone_frames[nf] = tuple(v0[k] + (v1[k] - v0[k]) * tt for k in range(3))
        result[bone] = bone_frames
    return result

# NUEVO (Kebyn, 2026-08-23, "la antorcha/mesa debe quedar adelante del
# personaje"): distancia (en unidades de escena) que se usa como destino
# de colocacion del objeto SOLO quando points[0] y points[1] son la MISMA
# coordenada -- caso real: el usuario reutiliza el punto siguiente para
# otra cosa (ej. marcarlo tambien como 'Parada' final, ver
# _expand_points_with_paradas() en path_recorder.py), asi que points[1]
# ya no representa "un paso mas adelante" sino el mismo lugar donde esta
# parado el personaje. Coincide con el espaciado real de la grilla de
# faces del escenario (ver capturas del usuario: puntos consecutivos
# separados exactamente 1.0 en X/Y).
OBJECT_PLACEMENT_FORWARD_STEP = 1.0


def _compute_object_placement_target(p0, p1, root_rot):
    """Calcula la coordenada donde debe quedar plantado el objeto
    (antorcha / mesa de crafteo) para generate_colocar_antorcha() y
    generate_colocar_mesa_crafteo().

    Caso normal (points[0] != points[1], el diseño original de
    'coordenadas REALES consecutivas, sin duplicar'): el destino es
    simplemente points[1], tal cual -- points[1] YA esta un paso
    adelante del personaje en el recorrido real.

    Caso points[0] == points[1] (mismas coords, redondeadas a 2
    decimales -- misma tolerancia que detect_movement_type()/
    _detect_move()): points[1] dejo de significar "un paso adelante" (es
    un duplicado usado para otra cosa, tipicamente cerrar el recorrido o
    marcar una Parada en el mismo lugar). En este caso el objeto NO debe
    aparecer clavado en el mismo punto donde esta parado el personaje --
    se calcula un punto sintetico OBJECT_PLACEMENT_FORWARD_STEP unidades
    adelante, en la direccion hacia la que el personaje esta orientado
    (root_rot[2], mismo angulo que usa _build_rotation_data() cuando
    _dir_angle es None por esta misma razon).

    FIX (Kebyn, "la esta colocando en sentido contrario"): la inversa
    matematica "ingenua" de _compute_direction_angle() (alla,
    ang = degrees(atan2(dx, dy))) seria dx = sin(ang), dy = cos(ang) --
    pero _compute_direction_angle() NO es una funcion pura atan2: tiene
    un flip explicito `if ang == 90: ang = -90 / elif ang == -90: ang = 90`
    para los dos casos cardinales sobre el eje X (ver su docstring/codigo).
    Verificado directo contra esa funcion con los 4 pasos cardinales
    (dx=+1, dx=-1, dy=+1, dy=-1): la correspondencia REAL resulto ser
    rz=-90 -> +X, rz=90 -> -X, rz=0 -> +Y, rz=180 -> -Y -- exactamente la
    inversa con el signo de X invertido respecto de la formula ingenua.
    Por eso aca se usa dx = -sin(ang) (no sin(ang)) para que el destino
    quede REALMENTE adelante del personaje y no atras.
    """
    x0, y0, z0 = round(p0['x'], 2), round(p0['y'], 2), round(p0['z'], 2)
    x1, y1, z1 = round(p1['x'], 2), round(p1['y'], 2), round(p1['z'], 2)
    if not (x0 == x1 and y0 == y1 and z0 == z1):
        return p1
    rad = math.radians(root_rot[2])
    fwd_x = -math.sin(rad) * OBJECT_PLACEMENT_FORWARD_STEP
    fwd_y = math.cos(rad) * OBJECT_PLACEMENT_FORWARD_STEP
    return {'x': p0['x'] + fwd_x, 'y': p0['y'] + fwd_y, 'z': p0['z']}


def _smoothstep_meta(x):
    """Smoothstep S-curve, version 'de generacion' (se ejecuta al armar el
    slot, no dentro del codigo generado -- por eso el sufijo _meta, para no
    confundirla con los _smoothstep_val/ease_in_out_* que SI viajan como
    texto dentro de los f-strings de codigo generado mas abajo)."""
    if x <= 0: return 0.0
    if x >= 1: return 1.0
    return x * x * (3.0 - 2.0 * x)


def _walk_pose_at_phase0(style_key):
    """Calcula, EN TIEMPO DE GENERACION (no en tiempo de ejecucion en
    Blender), la pose de piernas/rodillas/brazos/codos/columna/cuello que
    va a tener el PRIMER frame (walk_cycle=0) de un tramo 'caminar'
    generado con el estilo `style_key`.

    Replica BIT A BIT las mismas formulas biomecanicas que usa el codigo
    generado por generate_caminar() (calculate_leg_swing/calculate_arm_swing/
    calculate_elbow_flex/calculate_knee_flex, y las lineas de spine_forward/
    spine_tilt/neck_forward/neck_tilt/neck_side dentro de execute_animation)
    evaluadas en walk_cycle=0.

    NO USADA ACTUALMENTE (Kebyn): quedaba usada por
    _build_colocar_antorcha_keyframes() para armar una cola de transicion
    hacia la pose de caminata, tramo que fue reemplazado por el tramo de
    vuelta a POSE_PARADO (ver RETURN_TO_PARADO_FRAMES). Se deja la funcion
    aca, sin llamadas activas, por si hace falta reconstruir ese tipo de
    empalme mas adelante.
    """
    style = WALK_STYLE_PARAMS.get(style_key, WALK_STYLE_PARAMS['NORMAL'])
    rm = style['range_mult']
    ranges = {
        'arm_base_x':  math.radians(90 * rm['arm_base_x']),
        'arm_swing_y': math.radians(70 * rm['arm_swing_y']),
        'elbow_flex':  math.radians(50 * rm['elbow_flex']),
        'leg_swing_x': math.radians(50 * rm['leg_swing_x']),
        'knee_flex':   math.radians(40 * rm['knee_flex']),
        'spine_bend':  math.radians(0.1 * rm['spine_bend']),
        'neck_tilt':   math.radians(1.5 * rm['neck_tilt']),
        'head_stabilization': 0.25,
    }
    lean_forward    = style['lean_forward']
    asym_right_leg  = style['asym_right_leg']

    def _ease_in_out_sine(t):
        return -(math.cos(math.pi * t) - 1) / 2

    def _ease_in_out_cubic(t):
        if t < 0.5:
            return 4 * t * t * t
        return 1 - pow(-2 * t + 2, 3) / 2

    def _leg_swing(phase):
        return ranges['leg_swing_x'] * math.sin(phase * 2 * math.pi)

    def _arm_swing(phase):
        if phase < 0.5:
            t = phase / 0.5
            return _ease_in_out_sine(t) * ranges['arm_swing_y'] * 2 - ranges['arm_swing_y']
        else:
            t = (phase - 0.5) / 0.5
            return ranges['arm_swing_y'] - _ease_in_out_sine(t) * ranges['arm_swing_y'] * 2

    def _elbow_flex(phase):
        mf = ranges['elbow_flex']
        if phase < 0.3:
            t = phase / 0.3
            return _ease_in_out_sine(t) * mf * 0.85 + mf * 0.15
        elif phase < 0.7:
            t = (phase - 0.3) / 0.4
            return mf - _ease_in_out_cubic(t) * mf * 0.6
        else:
            t = (phase - 0.7) / 0.3
            return mf * 0.4 - _ease_in_out_sine(t) * mf * 0.25

    def _knee_flex(phase):
        mf = ranges['knee_flex']
        bump = math.sin((phase - 0.75) * 2 * math.pi)
        return mf * max(0.0, bump)

    walk_cycle = 0.0
    spine_forward = math.sin(walk_cycle * 2 * math.pi + math.pi / 6) * ranges['spine_bend'] + lean_forward
    spine_tilt    = math.cos(walk_cycle * 2 * math.pi + math.pi / 3) * ranges['spine_bend'] * 0.75
    neck_forward  = -spine_forward * ranges['head_stabilization']
    neck_tilt     = math.sin(walk_cycle * 2 * math.pi) * ranges['neck_tilt']
    neck_side     = math.cos(walk_cycle * 2 * math.pi + math.pi / 4) * ranges['neck_tilt'] * 0.5

    left_leg_swing   = _leg_swing(walk_cycle)
    left_knee_flex   = -_knee_flex(walk_cycle)
    right_leg_cycle  = (walk_cycle + 0.5) % 1.0
    right_leg_swing  = _leg_swing(right_leg_cycle) * (1.0 - asym_right_leg)
    right_knee_flex  = -_knee_flex(right_leg_cycle) * (1.0 - asym_right_leg)
    right_arm_phase  = (walk_cycle + 0.25) % 1.0
    right_arm_swing  = _arm_swing(right_arm_phase)
    right_elbow_flex = -_elbow_flex(right_arm_phase)
    left_arm_phase   = (walk_cycle + 0.75) % 1.0
    left_arm_swing   = -_arm_swing(left_arm_phase)
    left_elbow_flex  = _elbow_flex(left_arm_phase)

    return {
        'Body_cerdo_1':       (0.0, 0.0, 0.0),
        'Body:Bend_cerdo_1':      (spine_forward, 0.0, spine_tilt),
        'Body:Bend_cerdo_1':     (spine_forward, 0.0, spine_tilt),
        'Body:Bend_cerdo_1':     (spine_forward, 0.0, spine_tilt),
        'Head_cerdo_1':       (neck_forward, neck_side, neck_tilt),
        'Head_cerdo_1':       (0.0, 0.0, 0.0),
        'Leg:FL_cerdo_1':  (ranges['arm_base_x'], left_arm_swing, 0.0),
        'Leg:FL:Bend_cerdo_1':  (0.0, 0.0, left_elbow_flex),
        'Leg:FR_cerdo_1': (ranges['arm_base_x'], right_arm_swing, 0.0),
        'Leg:FR:Bend_cerdo_1': (0.0, 0.0, right_elbow_flex),
        'Leg:BL_cerdo_1':  (left_leg_swing, 0.0, 0.0),
        'Leg:BL:Bend_cerdo_1':   (left_knee_flex, 0.0, 0.0),
        'Leg:BR_cerdo_1': (right_leg_swing, 0.0, 0.0),
        'Leg:BR:Bend_cerdo_1':  (right_knee_flex, 0.0, 0.0),
    }


def _build_colocar_antorcha_keyframes(walk_style_next=None):
    """Combina la pose fija de KEYFRAMES_COLOCAR_ANTORCHA (frames 0-15:
    parado -> agachado plantando la antorcha) con el tramo RESTAURADO de
    vuelta a POSE_PARADO (frames 16..15+RETURN_TO_PARADO_FRAMES), que
    interpola en smoothstep desde la pose agachada (frame 15) de vuelta
    a la MISMA pose de pie del frame 0 de cada hueso (no hardcodeada:
    se toma directamente de KEYFRAMES_COLOCAR_ANTORCHA[bone][0], asi que
    si la pose parada cambia mas arriba, este tramo la sigue automatica-
    mente). Devuelve un dict nuevo con el mismo formato que
    KEYFRAMES_COLOCAR_ANTORCHA (bone -> {frame: (x,y,z)}), sin modificar
    la constante original.

    `walk_style_next` ya no se usa para construir este tramo (el slot
    vuelve a parado en vez de transicionar a la pose de caminata) -- se
    mantiene como parametro solo para no romper las llamadas existentes
    en path_recorder.py, que todavia lo pasan."""
    result = {}
    for bone, frames in KEYFRAMES_COLOCAR_ANTORCHA.items():
        bone_frames = dict(frames)
        start_val = frames[MID_FRAME_COLOCAR_ANTORCHA]
        end_val   = frames[0]
        for j in range(1, RETURN_TO_PARADO_FRAMES + 1):
            rel_frame = MID_FRAME_COLOCAR_ANTORCHA + j
            tt = _smoothstep_meta(j / RETURN_TO_PARADO_FRAMES)
            bone_frames[rel_frame] = tuple(
                start_val[k] + (end_val[k] - start_val[k]) * tt
                for k in range(3)
            )
        result[bone] = bone_frames
    return result


def _build_colocar_mesa_crafteo_keyframes(walk_style_next=None):
    """Version de _build_colocar_antorcha_keyframes() para
    KEYFRAMES_COLOCAR_MESA_CRAFTEO -- misma logica exacta (combina la pose
    fija 0-15 con el tramo de vuelta a POSE_PARADO interpolado en
    smoothstep), solo cambia el diccionario fuente. Ver docstring de
    _build_colocar_antorcha_keyframes() para el detalle completo."""
    result = {}
    for bone, frames in KEYFRAMES_COLOCAR_MESA_CRAFTEO.items():
        bone_frames = dict(frames)
        start_val = frames[MID_FRAME_COLOCAR_MESA_CRAFTEO]
        end_val   = frames[0]
        for j in range(1, RETURN_TO_PARADO_FRAMES + 1):
            rel_frame = MID_FRAME_COLOCAR_MESA_CRAFTEO + j
            tt = _smoothstep_meta(j / RETURN_TO_PARADO_FRAMES)
            bone_frames[rel_frame] = tuple(
                start_val[k] + (end_val[k] - start_val[k]) * tt
                for k in range(3)
            )
        result[bone] = bone_frames
    return result


def generate_colocar_antorcha(slot_index, start_frame, points, today, root_rot=(0, 0, -90),
                               walk_style_next='NORMAL'):
    """Genera un slot de 'colocar_antorcha': Cerdo_1 esta parado en
    points[0] (NO camina hacia points[1] -- ver ACTUALIZACION de abajo),
    se agacha y planta una antorcha en el suelo en points[1] (la
    coordenada REAL siguiente del recorrido, override manual de
    tipo_segmento -- ver detect_movement_type()). TOTAL_FRAMES_COLOCAR_ANTORCHA
    frames fijos, keyframes de pose en KEYFRAMES_COLOCAR_ANTORCHA
    (interpolacion real: parado -> inclinado_colocando_antorcha.json, ver
    comentario junto al diccionario) MAS el tramo RESTAURADO de vuelta a
    POSE_PARADO (ver RETURN_TO_PARADO_FRAMES / _build_colocar_antorcha_keyframes()).

    RESTAURADO (Kebyn): el slot vuelve a pararse al final -- termina en la
    pose agachada (frame 15) y de ahi vuelve (frames
    16..15+RETURN_TO_PARADO_FRAMES) a la MISMA pose de pie con la que
    arranco, en la MISMA coordenada (points[0], el root nunca se movio).
    El tramo "caminar" que group_segments() agrega automaticamente con los
    mismos points[0]/points[1] inmediatamente despues de este slot arranca
    tambien desde points[0] -- ese punto de partida no cambia, solo cambia
    la pose corporal con la que colocar_antorcha termina (parado en vez de
    agachado o en pose de zancada). `walk_style_next` ya no se usa para
    construir este tramo (ver _build_colocar_antorcha_keyframes()); se
    mantiene el parametro solo por compatibilidad con las llamadas
    existentes en path_recorder.py.

    ACTUALIZADO (Kebyn, 2026-08-21): el root/Empty "cerdo_1" NO se
    desplaza durante este slot -- ROOT_LOCATION_DATA queda fijo en
    points[0] (de punta a punta del slot). points[1] solo se usa
    como destino de la ANTORCHA (objeto aparte) y como referencia de
    orientacion (el personaje sigue girando para encarar hacia points[1]
    antes de agacharse, ver ROOT_ROTATION_DATA/_build_rotation_data() mas
    abajo -- eso no cambio). Si el recorrido necesita que el personaje
    camine hasta ahi, eso lo cubre el tramo 'caminar' previo del
    recorrido, no este slot.

    La IMPORTACION/COLOCACION de la antorcha en si NO se anima aca --
    ese es el trabajo del Sistema de Lanzar/Recoger/Mantener Objetos
    (seg.throws, ver Cerdo_1ThrowItem/apply_throw_item en
    operators_anim.py). Este generador solo deja la metadata
    TORCH_TARGET_COORDS (= points[1]) y TORCH_APPEAR_FRAME (= start_frame
    + MID_FRAME_COLOCAR_ANTORCHA, el frame exacto en el que el cuerpo
    esta en la pose de inclinado_colocando_antorcha.json) para que
    CERDO_1SEG_OT_AutoSplitFromConfig (operators_segments.py) y
    "Reproducir recorrido" (path_recorder.py) registren/importen la
    antorcha oculta hasta ese frame exacto -- NUNCA antes, y sin
    trayectoria de lanzamiento: aparece de golpe en ese instante,
    plantada, con transition_out='NONE' (se queda fija en el suelo).
    Fuente antorcha_1.blend (bloques_dinamicos/antorcha_1/antorcha_1.blend).
    """
    total_frames = TOTAL_FRAMES_COLOCAR_ANTORCHA
    end_frame = start_frame + total_frames - 1
    torch_appear_frame = start_frame + MID_FRAME_COLOCAR_ANTORCHA
    p0 = points[0]['coordinates']
    p1 = points[1]['coordinates']
    # FIX (Kebyn, "la antorcha debe quedar adelante del personaje"): si
    # points[1] resulto ser la MISMA coordenada que points[0] (punto
    # reutilizado en la lista para otra cosa, ej. tambien marcado como
    # Parada final -- ver _expand_points_with_paradas()), plantar la
    # antorcha literalmente en points[1] la dejaba clavada en el mismo
    # lugar donde esta parado el personaje. target_coords calcula un
    # punto un paso adelante en esos casos; en el caso normal
    # (points[0] != points[1]) es identico a p1, sin cambios de
    # comportamiento.
    target_coords = _compute_object_placement_target(p0, p1, root_rot)
    traj = _fmt_trajectory(points)
    kf = _fmt_keyframes(_build_colocar_antorcha_keyframes(walk_style_next), start_frame)
    rx, ry, rz = root_rot

    code = f'''# -*- coding: utf-8 -*-
"""
slot_{slot_index:03d}_colocar_antorcha.py
Cerdo_1 - Slot {slot_index}

GENERADO AUTOMATICAMENTE
Fecha de generacion: {today}

NOTA: este slot anima a Cerdo_1 agachandose y plantando una antorcha en
el suelo en points[1], SIN desplazar el root (permanece parado en
points[0] todo el slot). La antorcha misma (importacion + colocacion)
la maneja el sistema de Lanzar/Recoger/Mantener Objetos (seg.throws) --
ver TORCH_TARGET_COORDS/TORCH_APPEAR_FRAME mas abajo.
"""

import bpy
import math

# --- Compatibilidad Action.fcurves (eliminado en Blender 5.0+, ver slots/channelbags) ---
def _get_fcurves(target):
    anim_data = None
    action = target
    if isinstance(target, bpy.types.AnimData):
        anim_data = target
        action = anim_data.action
    if action is None:
        return []
    if hasattr(action, 'fcurves'):
        return action.fcurves
    from bpy_extras import anim_utils as _au
    slot = anim_data.action_slot if anim_data is not None else None
    if slot is None and action.slots:
        slot = action.slots[0]
    if slot is None:
        return []
    channelbag = _au.action_ensure_channelbag_for_slot(action, slot)
    return channelbag.fcurves if channelbag else []

# ============================================
# CONFIGURACION DEL SLOT
# ============================================

SLOT_INDEX = {slot_index}
START_FRAME = {start_frame}
END_FRAME = {end_frame}  # {start_frame} + {total_frames} - 1
TOTAL_FRAMES = {total_frames}

# ============================================
# DATOS DE TRAYECTORIA EMBEBIDOS - SLOT {slot_index}
# ============================================

{traj}

# ============================================
# FIN DE CONFIGURACION DEL SLOT {slot_index}
# ============================================

ANIMATION_INFO = {{
    'name': 'slot_{slot_index:03d}_colocar_antorcha.py',
    'frame_count': {total_frames},
    'fps': 24,
    'duration_seconds': {total_frames/24:.2f},
    'entity': 'Cerdo_1',
    'slot': {slot_index},
    'movement_type': 'colocar_antorcha',
    'narrative_importance': 'prop_placement',
    'rig_type': 'full_armature',
    'source': 'cerdo_1_rig',
    'bones_animated': 14,
    'animation_type': 'crouch_place_object',
}}

# Root Location: FIJO en posicion {points[0]['index']} {(p0['x'], p0['y'], p0['z'])}
# durante los {total_frames} frames -- el personaje esta parado ahi, no
# camina hacia points[1] (esa coordenada solo la usa la antorcha).

ROOT_LOCATION_DATA = {{
    {start_frame}: ({p0['x']}, {p0['y']}, {p0['z']}),
    {end_frame}: ({p0['x']}, {p0['y']}, {p0['z']}),
}}

# Coordenada donde debe quedar la antorcha plantada (consumida por
# CERDO_1SEG_OT_AutoSplitFromConfig para auto-registrar el Cerdo_1ThrowItem).
TORCH_TARGET_COORDS = {{'x': {target_coords['x']}, 'y': {target_coords['y']}, 'z': {target_coords['z']}}}
# Frame ABSOLUTO en el que el cuerpo esta exactamente en la pose de
# inclinado_colocando_antorcha.json -- la antorcha debe permanecer
# oculta hasta este frame exacto y aparecer recien aca (sin trayectoria
# de lanzamiento, sin adelantarse ni atrasarse).
TORCH_APPEAR_FRAME = {torch_appear_frame}
TORCH_SOURCE = {{
    'object_folder': 'bloques_dinamicos',
    'blend_filename': 'antorcha_1.blend',
    'object_name': 'antorcha_1',
}}

def _compute_direction_angle(p0, p1):
    """Angulo de orientacion cardinal/diagonal para el segmento p0->p1."""
    dx = p1['x'] - p0['x']
    dy = p1['y'] - p0['y']
    if dx == 0 and dy == 0:
        return None
    ang_raw = math.degrees(math.atan2(dx, dy))
    ang_rounded = round(ang_raw / 90.0) * 90.0
    ang_diff = abs(ang_raw - ang_rounded)
    ang = ang_rounded if ang_diff < 45 else -ang_raw
    while ang >  180: ang -= 360
    while ang < -180: ang += 360
    if   ang ==  90: ang = -90
    elif ang == -90: ang =  90
    return ang

def _smoothstep_val(x):
    if x <= 0: return 0.0
    if x >= 1: return 1.0
    return x * x * (3.0 - 2.0 * x)

def _angle_diff_shortest(target, current):
    d = target - current
    while d >  180: d -= 360
    while d < -180: d += 360
    return d

# --- Orientacion por trayectoria (p0->p1) con RotationSmoother, igual
# que en saltar_subir/saltar_bajar ---
_p0_coords = {{'x': {p0['x']}, 'y': {p0['y']}, 'z': {p0['z']}}}
_p1_coords = {{'x': {p1['x']}, 'y': {p1['y']}, 'z': {p1['z']}}}
_dir_angle  = _compute_direction_angle(_p0_coords, _p1_coords)
_base_rz    = {rz}

def _build_rotation_data():
    import math as _math
    data = {{}}
    target_rz = _dir_angle if _dir_angle is not None else _base_rz
    smoothing = 10

    prev_rot  = _base_rz
    trans_start = None
    trans_start_rot = None

    for frame in range({start_frame}, {end_frame + 1}):
        angle_diff = _angle_diff_shortest(target_rz, prev_rot)
        if abs(angle_diff) < 0.1:
            smoothed = target_rz
            trans_start = None
        else:
            if trans_start is None:
                trans_start = frame
                trans_start_rot = prev_rot
            elapsed  = frame - trans_start
            progress = min(elapsed / smoothing, 1.0)
            eased    = _smoothstep_val(progress)
            smoothed = trans_start_rot + _angle_diff_shortest(target_rz, trans_start_rot) * eased
            if progress >= 1.0:
                prev_rot   = target_rz
                trans_start = None

        data[frame] = (_math.radians({rx}), _math.radians({ry}), _math.radians(smoothed))
    return data

ROOT_ROTATION_DATA = _build_rotation_data()
ROOT_ROTATION_X = {rx}
ROOT_ROTATION_Y = {ry}
ROOT_ROTATION_Z = {rz}

{kf}


def execute_animation(player_parts, start_frame=None, end_frame=None):
    """
    Slot {slot_index}: 'Colocar antorcha' de Cerdo_1 -- camina hasta el
    punto, se agacha, planta la antorcha en el suelo y se levanta.
    """
    start_frame = START_FRAME
    end_frame = END_FRAME

    armature = bpy.data.objects.get("pig.arma_cerdo_1")
    if not armature or armature.type != 'ARMATURE':
        print("Error: No se encontro el Armature")
        return False

    if armature.mode != 'POSE':
        bpy.context.view_layer.objects.active = armature
        bpy.ops.object.mode_set(mode='POSE')

    cerdo_1_root = next((o for o in bpy.data.objects if o.name == 'cerdo_1' and o.type == 'EMPTY'), None)

    _arm_action_name  = f'slot_{slot_index:03d}_cerdo_1_colocar_antorcha_arm'
    _root_action_name = f'slot_{slot_index:03d}_cerdo_1_colocar_antorcha_root'

    if not armature.animation_data:
        armature.animation_data_create()
    _arm_existing = bpy.data.actions.get(_arm_action_name)
    if _arm_existing:
        bpy.data.actions.remove(_arm_existing)
    _arm_action = bpy.data.actions.new(name=_arm_action_name)
    armature.animation_data.action = _arm_action

    _bones_ok = 0
    for _bone_name, _frames in globals()['KEYFRAME_DATA'].items():
        _bone = armature.pose.bones.get(_bone_name)
        if not _bone:
            continue
        _bone.rotation_mode = 'XYZ'
        for _frame, _rot in _frames.items():
            _bone.rotation_euler = _rot
            _bone.keyframe_insert(data_path="rotation_euler", frame=_frame)
        _bones_ok += 1

    for _fc in _get_fcurves(_arm_action):
        for _kp in _fc.keyframe_points:
            _kp.interpolation = 'BEZIER'
            _kp.easing = 'AUTO'

    if cerdo_1_root is not None:
        if not cerdo_1_root.animation_data:
            cerdo_1_root.animation_data_create()
        _root_existing = bpy.data.actions.get(_root_action_name)
        if _root_existing:
            bpy.data.actions.remove(_root_existing)
        _root_action = bpy.data.actions.new(name=_root_action_name)
        cerdo_1_root.animation_data.action = _root_action

        for _frame in sorted(ROOT_LOCATION_DATA.keys()):
            cerdo_1_root.location = ROOT_LOCATION_DATA[_frame]
            cerdo_1_root.keyframe_insert(data_path="location", frame=_frame)
        for _frame in sorted(ROOT_ROTATION_DATA.keys()):
            cerdo_1_root.rotation_euler = ROOT_ROTATION_DATA[_frame]
            cerdo_1_root.keyframe_insert(data_path="rotation_euler", frame=_frame)

        for _fc in _get_fcurves(_root_action):
            for _kp in _fc.keyframe_points:
                _kp.interpolation = 'BEZIER'
                _kp.easing = 'AUTO'

    print(f"[Slot {slot_index}] colocar_antorcha aplicado ({{_bones_ok}} bones, "
          f"{{start_frame}}-{{end_frame}}), antorcha destino: {{TORCH_TARGET_COORDS}}")

    # ============================================
    # EMPUJAR ACCIONES AL NLA
    # ============================================
    # FIX (Kebyn, 2026-08-21): sin este bloque (presente en generate_saltar_subir/
    # generate_saltar_bajar/generate_caminar pero faltante aca) la accion de este
    # slot quedaba como armature.animation_data.action "suelta" -- el SIGUIENTE
    # slot del recorrido la pisaba al asignar la suya propia, y el bake final
    # (bpy.ops.nla.bake sobre los NLA tracks) no encontraba NINGUN strip cubriendo
    # este rango de frames, dejando a Cerdo_1 en pose T durante todo el tramo
    # colocar_antorcha (tanto en Reproducir recorrido como en la exportacion).
    if armature.animation_data and armature.animation_data.action:
        _arm_done  = armature.animation_data.action
        armature.animation_data.action = None
        _arm_track = armature.animation_data.nla_tracks.new()
        _arm_track.name = f'Slot_{slot_index:03d}_arm'
        _arm_strip = _arm_track.strips.new(_arm_done.name, start_frame, _arm_done)
        _arm_strip.frame_end      = end_frame
        _arm_strip.extrapolation  = 'NOTHING'
        _arm_strip.use_auto_blend = False
        _arm_strip.blend_in       = 0
        _arm_strip.blend_out      = 0

    if cerdo_1_root and cerdo_1_root.animation_data and cerdo_1_root.animation_data.action:
        _root_done  = cerdo_1_root.animation_data.action
        cerdo_1_root.animation_data.action = None
        _root_track = cerdo_1_root.animation_data.nla_tracks.new()
        _root_track.name = f'Slot_{slot_index:03d}_root'
        _root_strip = _root_track.strips.new(_root_done.name, start_frame, _root_done)
        _root_strip.frame_end      = end_frame
        _root_strip.extrapolation  = 'HOLD_FORWARD'
        _root_strip.use_auto_blend = False
        _root_strip.blend_in       = 0
        _root_strip.blend_out      = 0

    return True
'''
    return code, end_frame


def generate_colocar_mesa_crafteo(slot_index, start_frame, points, today, root_rot=(0, 0, -90),
                                   walk_style_next='NORMAL'):
    """Genera un slot de 'colocar_mesa_de_crafteo': Cerdo_1 esta parado en
    points[0] (NO camina hacia points[1]), se agacha y coloca una mesa de
    crafteo en el suelo en points[1] (la coordenada REAL siguiente del
    recorrido, override manual de tipo_segmento -- ver
    detect_movement_type()). Misma arquitectura EXACTA que
    generate_colocar_antorcha(): TOTAL_FRAMES_COLOCAR_MESA_CRAFTEO frames
    fijos, keyframes de pose en KEYFRAMES_COLOCAR_MESA_CRAFTEO
    (interpolacion real: parado -> colocando_mesa_de_crafteo.json) MAS el
    tramo de vuelta a POSE_PARADO (ver RETURN_TO_PARADO_FRAMES /
    _build_colocar_mesa_crafteo_keyframes()).

    El root/Empty "cerdo_1" NO se desplaza durante este slot --
    ROOT_LOCATION_DATA queda fijo en points[0] de punta a punta. points[1]
    solo se usa como destino de la MESA (objeto aparte) y como referencia
    de orientacion (el personaje gira para encarar hacia points[1] antes
    de agacharse, igual que en colocar_antorcha). El tramo "caminar" que
    group_segments() inyecta automaticamente justo despues (mismos 2
    puntos) es quien recorre la distancia real hasta donde quedo la mesa.

    La IMPORTACION/COLOCACION de la mesa en si NO se anima aca -- ese es
    el trabajo del Sistema de Lanzar/Recoger/Mantener Objetos (seg.throws,
    ver Cerdo_1ThrowItem/apply_throw_item en operators_anim.py). Este
    generador solo deja la metadata TABLE_TARGET_COORDS (= points[1]) y
    TABLE_APPEAR_FRAME (= start_frame + MID_FRAME_COLOCAR_MESA_CRAFTEO, el
    frame exacto en el que el cuerpo esta en la pose de
    colocando_mesa_de_crafteo.json) para que CERDO_1SEG_OT_AutoSplitFromConfig
    (operators_segments.py) y "Reproducir recorrido" (path_recorder.py)
    registren/importen la mesa oculta hasta ese frame exacto -- nunca
    antes, sin trayectoria de lanzamiento: aparece de golpe en ese
    instante, plantada, con transition_out='NONE' (se queda fija en el
    suelo). Fuente mesa_de_crafteo_1.blend
    (bloques_dinamicos/mesa_de_crafteo_1/mesa_de_crafteo_1.blend). Las
    siguientes mesas del mismo recorrido se numeran solas
    (mesa_de_crafteo_2, mesa_de_crafteo_3...) via
    aplicar_sufijo_numerico_anticolision(), exactamente igual que con
    antorcha_1/antorcha_2/antorcha_3.
    """
    total_frames = TOTAL_FRAMES_COLOCAR_MESA_CRAFTEO
    end_frame = start_frame + total_frames - 1
    table_appear_frame = start_frame + MID_FRAME_COLOCAR_MESA_CRAFTEO
    p0 = points[0]['coordinates']
    p1 = points[1]['coordinates']
    # FIX (Kebyn, "la mesa debe quedar adelante del personaje"): mismo fix
    # que generate_colocar_antorcha() -- ver comentario detallado ahi.
    target_coords = _compute_object_placement_target(p0, p1, root_rot)
    traj = _fmt_trajectory(points)
    kf = _fmt_keyframes(_build_colocar_mesa_crafteo_keyframes(walk_style_next), start_frame)
    rx, ry, rz = root_rot

    code = f'''# -*- coding: utf-8 -*-
"""
slot_{slot_index:03d}_colocar_mesa_de_crafteo.py
Cerdo_1 - Slot {slot_index}

GENERADO AUTOMATICAMENTE
Fecha de generacion: {today}

NOTA: este slot anima a Cerdo_1 agachandose y colocando una mesa de
crafteo en el suelo en points[1], SIN desplazar el root (permanece
parado en points[0] todo el slot). La mesa misma (importacion +
colocacion) la maneja el sistema de Lanzar/Recoger/Mantener Objetos
(seg.throws) -- ver TABLE_TARGET_COORDS/TABLE_APPEAR_FRAME mas abajo.
"""

import bpy
import math

# --- Compatibilidad Action.fcurves (eliminado en Blender 5.0+, ver slots/channelbags) ---
def _get_fcurves(target):
    anim_data = None
    action = target
    if isinstance(target, bpy.types.AnimData):
        anim_data = target
        action = anim_data.action
    if action is None:
        return []
    if hasattr(action, 'fcurves'):
        return action.fcurves
    from bpy_extras import anim_utils as _au
    slot = anim_data.action_slot if anim_data is not None else None
    if slot is None and action.slots:
        slot = action.slots[0]
    if slot is None:
        return []
    channelbag = _au.action_ensure_channelbag_for_slot(action, slot)
    return channelbag.fcurves if channelbag else []

# ============================================
# CONFIGURACION DEL SLOT
# ============================================

SLOT_INDEX = {slot_index}
START_FRAME = {start_frame}
END_FRAME = {end_frame}  # {start_frame} + {total_frames} - 1
TOTAL_FRAMES = {total_frames}

# ============================================
# DATOS DE TRAYECTORIA EMBEBIDOS - SLOT {slot_index}
# ============================================

{traj}

# ============================================
# FIN DE CONFIGURACION DEL SLOT {slot_index}
# ============================================

ANIMATION_INFO = {{
    'name': 'slot_{slot_index:03d}_colocar_mesa_de_crafteo.py',
    'frame_count': {total_frames},
    'fps': 24,
    'duration_seconds': {total_frames/24:.2f},
    'entity': 'Cerdo_1',
    'slot': {slot_index},
    'movement_type': 'colocar_mesa_de_crafteo',
    'narrative_importance': 'prop_placement',
    'rig_type': 'full_armature',
    'source': 'cerdo_1_rig',
    'bones_animated': 14,
    'animation_type': 'crouch_place_object',
}}

# Root Location: FIJO en posicion {points[0]['index']} {(p0['x'], p0['y'], p0['z'])}
# durante los {total_frames} frames -- el personaje esta parado ahi, no
# camina hacia points[1] (esa coordenada solo la usa la mesa de crafteo).

ROOT_LOCATION_DATA = {{
    {start_frame}: ({p0['x']}, {p0['y']}, {p0['z']}),
    {end_frame}: ({p0['x']}, {p0['y']}, {p0['z']}),
}}

# Coordenada donde debe quedar la mesa de crafteo colocada (consumida por
# CERDO_1SEG_OT_AutoSplitFromConfig para auto-registrar el Cerdo_1ThrowItem).
TABLE_TARGET_COORDS = {{'x': {target_coords['x']}, 'y': {target_coords['y']}, 'z': {target_coords['z']}}}
# Frame ABSOLUTO en el que el cuerpo esta exactamente en la pose de
# colocando_mesa_de_crafteo.json -- la mesa debe permanecer oculta hasta
# este frame exacto y aparecer recien aca (sin trayectoria de lanzamiento,
# sin adelantarse ni atrasarse).
TABLE_APPEAR_FRAME = {table_appear_frame}
TABLE_SOURCE = {{
    'object_folder': 'bloques_dinamicos',
    'blend_filename': 'mesa_de_crafteo_1.blend',
    'object_name': 'mesa_de_crafteo_1',
}}

def _compute_direction_angle(p0, p1):
    """Angulo de orientacion cardinal/diagonal para el segmento p0->p1."""
    dx = p1['x'] - p0['x']
    dy = p1['y'] - p0['y']
    if dx == 0 and dy == 0:
        return None
    ang_raw = math.degrees(math.atan2(dx, dy))
    ang_rounded = round(ang_raw / 90.0) * 90.0
    ang_diff = abs(ang_raw - ang_rounded)
    ang = ang_rounded if ang_diff < 45 else -ang_raw
    while ang >  180: ang -= 360
    while ang < -180: ang += 360
    if   ang ==  90: ang = -90
    elif ang == -90: ang =  90
    return ang

def _smoothstep_val(x):
    if x <= 0: return 0.0
    if x >= 1: return 1.0
    return x * x * (3.0 - 2.0 * x)

def _angle_diff_shortest(target, current):
    d = target - current
    while d >  180: d -= 360
    while d < -180: d += 360
    return d

# --- Orientacion por trayectoria (p0->p1) con RotationSmoother, igual
# que en saltar_subir/saltar_bajar/colocar_antorcha ---
_p0_coords = {{'x': {p0['x']}, 'y': {p0['y']}, 'z': {p0['z']}}}
_p1_coords = {{'x': {p1['x']}, 'y': {p1['y']}, 'z': {p1['z']}}}
_dir_angle  = _compute_direction_angle(_p0_coords, _p1_coords)
_base_rz    = {rz}

def _build_rotation_data():
    import math as _math
    data = {{}}
    target_rz = _dir_angle if _dir_angle is not None else _base_rz
    smoothing = 10

    prev_rot  = _base_rz
    trans_start = None
    trans_start_rot = None

    for frame in range({start_frame}, {end_frame + 1}):
        angle_diff = _angle_diff_shortest(target_rz, prev_rot)
        if abs(angle_diff) < 0.1:
            smoothed = target_rz
            trans_start = None
        else:
            if trans_start is None:
                trans_start = frame
                trans_start_rot = prev_rot
            elapsed  = frame - trans_start
            progress = min(elapsed / smoothing, 1.0)
            eased    = _smoothstep_val(progress)
            smoothed = trans_start_rot + _angle_diff_shortest(target_rz, trans_start_rot) * eased
            if progress >= 1.0:
                prev_rot   = target_rz
                trans_start = None

        data[frame] = (_math.radians({rx}), _math.radians({ry}), _math.radians(smoothed))
    return data

ROOT_ROTATION_DATA = _build_rotation_data()
ROOT_ROTATION_X = {rx}
ROOT_ROTATION_Y = {ry}
ROOT_ROTATION_Z = {rz}

{kf}


def execute_animation(player_parts, start_frame=None, end_frame=None):
    """
    Slot {slot_index}: 'Colocar mesa de crafteo' de Cerdo_1 -- se agacha,
    coloca la mesa de crafteo en el suelo y se levanta.
    """
    start_frame = START_FRAME
    end_frame = END_FRAME

    armature = bpy.data.objects.get("pig.arma_cerdo_1")
    if not armature or armature.type != 'ARMATURE':
        print("Error: No se encontro el Armature")
        return False

    if armature.mode != 'POSE':
        bpy.context.view_layer.objects.active = armature
        bpy.ops.object.mode_set(mode='POSE')

    cerdo_1_root = next((o for o in bpy.data.objects if o.name == 'cerdo_1' and o.type == 'EMPTY'), None)

    _arm_action_name  = f'slot_{slot_index:03d}_cerdo_1_colocar_mesa_de_crafteo_arm'
    _root_action_name = f'slot_{slot_index:03d}_cerdo_1_colocar_mesa_de_crafteo_root'

    if not armature.animation_data:
        armature.animation_data_create()
    _arm_existing = bpy.data.actions.get(_arm_action_name)
    if _arm_existing:
        bpy.data.actions.remove(_arm_existing)
    _arm_action = bpy.data.actions.new(name=_arm_action_name)
    armature.animation_data.action = _arm_action

    _bones_ok = 0
    for _bone_name, _frames in globals()['KEYFRAME_DATA'].items():
        _bone = armature.pose.bones.get(_bone_name)
        if not _bone:
            continue
        _bone.rotation_mode = 'XYZ'
        for _frame, _rot in _frames.items():
            _bone.rotation_euler = _rot
            _bone.keyframe_insert(data_path="rotation_euler", frame=_frame)
        _bones_ok += 1

    for _fc in _get_fcurves(_arm_action):
        for _kp in _fc.keyframe_points:
            _kp.interpolation = 'BEZIER'
            _kp.easing = 'AUTO'

    if cerdo_1_root is not None:
        if not cerdo_1_root.animation_data:
            cerdo_1_root.animation_data_create()
        _root_existing = bpy.data.actions.get(_root_action_name)
        if _root_existing:
            bpy.data.actions.remove(_root_existing)
        _root_action = bpy.data.actions.new(name=_root_action_name)
        cerdo_1_root.animation_data.action = _root_action

        for _frame in sorted(ROOT_LOCATION_DATA.keys()):
            cerdo_1_root.location = ROOT_LOCATION_DATA[_frame]
            cerdo_1_root.keyframe_insert(data_path="location", frame=_frame)
        for _frame in sorted(ROOT_ROTATION_DATA.keys()):
            cerdo_1_root.rotation_euler = ROOT_ROTATION_DATA[_frame]
            cerdo_1_root.keyframe_insert(data_path="rotation_euler", frame=_frame)

        for _fc in _get_fcurves(_root_action):
            for _kp in _fc.keyframe_points:
                _kp.interpolation = 'BEZIER'
                _kp.easing = 'AUTO'

    print(f"[Slot {slot_index}] colocar_mesa_de_crafteo aplicado ({{_bones_ok}} bones, "
          f"{{start_frame}}-{{end_frame}}), mesa destino: {{TABLE_TARGET_COORDS}}")

    # ============================================
    # EMPUJAR ACCIONES AL NLA
    # ============================================
    # Mismo fix que en colocar_antorcha: sin este bloque la accion de este
    # slot queda "suelta" y el bake final no encuentra ningun strip
    # cubriendo este rango de frames.
    if armature.animation_data and armature.animation_data.action:
        _arm_done  = armature.animation_data.action
        armature.animation_data.action = None
        _arm_track = armature.animation_data.nla_tracks.new()
        _arm_track.name = f'Slot_{slot_index:03d}_arm'
        _arm_strip = _arm_track.strips.new(_arm_done.name, start_frame, _arm_done)
        _arm_strip.frame_end      = end_frame
        _arm_strip.extrapolation  = 'NOTHING'
        _arm_strip.use_auto_blend = False
        _arm_strip.blend_in       = 0
        _arm_strip.blend_out      = 0

    if cerdo_1_root and cerdo_1_root.animation_data and cerdo_1_root.animation_data.action:
        _root_done  = cerdo_1_root.animation_data.action
        cerdo_1_root.animation_data.action = None
        _root_track = cerdo_1_root.animation_data.nla_tracks.new()
        _root_track.name = f'Slot_{slot_index:03d}_root'
        _root_strip = _root_track.strips.new(_root_done.name, start_frame, _root_done)
        _root_strip.frame_end      = end_frame
        _root_strip.extrapolation  = 'HOLD_FORWARD'
        _root_strip.use_auto_blend = False
        _root_strip.blend_in       = 0
        _root_strip.blend_out      = 0

    return True
'''
    return code, end_frame


# ============================================================
# CREAR_PARED_NXN - grilla de bloques de 1m3 (Kebyn, pedido
# "crear pared NxN bloques")
# ============================================================
# NUEVO (Kebyn): misma arquitectura EXACTA que "colocar_mesa_de_crafteo"
# de arriba -- abarca DOS coordenadas REALES consecutivas del recorrido
# (points[0]/points[1]), override manual de tipo_segmento (ver
# detect_movement_type()). El root/Empty "cerdo_1" queda FIJO en points[0]
# durante TODO el slot -- el tramo "caminar" que group_segments() fusiona
# automaticamente justo despues (mismos 2 puntos) es quien recorre la
# distancia real. La diferencia con colocar_mesa_de_crafteo es que aca el
# ciclo agachar/colocar/parar de _build_colocar_mesa_crafteo_keyframes()
# se repite UNA VEZ POR CADA BLOQUE de la grilla Filas x Columnas
# (pared_filas/pared_columnas, elegidas por Kebyn en el punto, Paso 1),
# concatenados sin superponerse -- ver FRAMES_PER_BLOQUE_PARED_NXN y
# _build_crear_pared_nxn_keyframes() mas abajo.


def _build_crear_pared_nxn_keyframes(num_bloques, walk_style_next=None, frames_per_bloque=None):
    """Repite el ciclo completo de _build_colocar_mesa_crafteo_keyframes()
    (parado -> agachado colocando -> parado otra vez) una vez por cada
    bloque de la grilla, concatenados en el tiempo SIN superponerse (el
    bloque i+1 arranca en el frame relativo i*frames_per_bloque,
    exactamente donde el bloque i termina ya de pie -- el ciclo es
    continuo porque el ultimo frame de cada ciclo vuelve a la MISMA pose
    parada con la que arranca el siguiente).

    frames_per_bloque (NUEVO, "elegir cuantos frames dura toda la
    animacion de crear pared"): si es None o coincide con
    FRAMES_PER_BLOQUE_PARED_NXN, el ciclo se usa tal cual (comportamiento
    de siempre). Si Kebyn eligio un total de frames y
    resolve_pared_nxn_timing() calculo un frames_per_bloque distinto, el
    ciclo se reescala primero via _resample_bone_cycle() para que cada
    bloque dure exactamente frames_per_bloque frames.

    Devuelve el mismo formato bone -> {frame: (x,y,z)} que el resto de
    generadores, con frames relativos 0..(frames_per_bloque *
    num_bloques - 1)."""
    single_cycle = _build_colocar_mesa_crafteo_keyframes(walk_style_next)
    if frames_per_bloque is None:
        frames_per_bloque = FRAMES_PER_BLOQUE_PARED_NXN
    if frames_per_bloque != FRAMES_PER_BLOQUE_PARED_NXN:
        single_cycle = _resample_bone_cycle(
            single_cycle, FRAMES_PER_BLOQUE_PARED_NXN, frames_per_bloque)
    result = {}
    for bone, frames in single_cycle.items():
        bone_frames = {}
        for i in range(max(1, num_bloques)):
            offset = i * frames_per_bloque
            for frame, rot in frames.items():
                bone_frames[frame + offset] = rot
        result[bone] = bone_frames
    return result


def _compute_wall_grid_coords(p0, p1, root_rot, filas, columnas, block_size=1.0):
    """Calcula las coordenadas (mundo) de cada celda de la grilla
    Filas x Columnas de la pared, CENTRADA en el mismo punto de
    colocacion que usarian generate_colocar_antorcha()/
    generate_colocar_mesa_crafteo() (_compute_object_placement_target(),
    ver ese comentario para el caso degenerado points[0]==points[1]).

    Las COLUMNAS se reparten a los costados de ese punto central, en la
    direccion PERPENDICULAR hacia la que el personaje esta orientado
    (misma orientacion que calcula _build_rotation_data() mas abajo, via
    _compute_direction_angle()) -- por eso la pared queda "de frente" al
    recorrido, no clavada de canto. Las FILAS se apilan hacia ARRIBA en
    Z, con la fila 0 al ras del suelo (misma Z que el punto de
    colocacion) y las siguientes filas sumando block_size (1m, el mismo
    tamaño del bloque de 1m3) cada una.

    Devuelve una lista de dicts {'row', 'col', 'x', 'y', 'z'}, en orden
    fila-por-fila (fila 0 completa, izquierda a derecha, despues fila 1,
    etc.) -- ese es tambien el orden en que se van a colocar los
    bloques uno por uno a lo largo del slot (ver generate_crear_pared_nxn()).
    """
    target = _compute_object_placement_target(p0, p1, root_rot)
    ang = _compute_direction_angle(p0, p1)
    if ang is None:
        ang = root_rot[2]
    rad = math.radians(ang)
    # Vector perpendicular al frente (mismo signo que el "fwd" de
    # _compute_object_placement_target, rotado 90 grados) -- unidad de
    # desplazamiento "hacia el costado" para separar las columnas.
    side_x = math.cos(rad)
    side_y = math.sin(rad)
    grid = []
    for r in range(max(1, filas)):
        for c in range(max(1, columnas)):
            offset_c = (c - (columnas - 1) / 2.0) * block_size
            grid.append({
                'row': r,
                'col': c,
                'x': target['x'] + side_x * offset_c,
                'y': target['y'] + side_y * offset_c,
                'z': target['z'] + r * block_size,
                # NUEVO (fix "bloques en direcciones distintas"): heading
                # de la pared (mismo angulo `ang` usado arriba para las
                # columnas), en RADIANES, listo para asignarse tal cual a
                # Cerdo_1ThrowItem.rot_z -- asi TODOS los bloques de la
                # grilla quedan orientados igual entre si (de frente al
                # recorrido), en vez de heredar la rotacion instantanea de
                # la mano que los "coloca" (ver fix en apply_throw_item,
                # operators_anim.py).
                'rot_z': rad,
            })
    return grid


def generate_crear_pared_nxn(slot_index, start_frame, points, today, root_rot=(0, 0, -90),
                              walk_style_next='NORMAL'):
    """Genera un slot de 'crear_pared_nxn': Cerdo_1 esta parado en
    points[0] (NO camina hacia points[1] -- mismo mecanismo que
    generate_colocar_mesa_crafteo(), el tramo "caminar" que
    group_segments() fusiona automaticamente justo despues es quien
    recorre la distancia real). En vez de un solo objeto, coloca UNA
    GRILLA de Filas x Columnas bloques de 1m3 frente a el, uno por uno --
    cada bloque tiene su propio ciclo completo agachar/colocar/parar,
    normalmente de FRAMES_PER_BLOQUE_PARED_NXN frames -- salvo que Kebyn
    haya elegido un total de frames para TODA la animacion (punto,
    Paso 1, campo "Frames totales"), en cuyo caso ese total se reparte
    entre los bloques y el ciclo se reescala a la duracion resultante
    (ver resolve_pared_nxn_timing()/_resample_bone_cycle() mas arriba).

    Filas/columnas, el archivo .blend del bloque (elegido por Kebyn en
    el panel del Paso 1, campo "Bloque .blend (1m3)") y el total de
    frames opcional viajan en points[0] ("pared_filas"/"pared_columnas"/
    "pared_bloque_blend_path"/"pared_total_frames" -- ver key_points en
    path_recorder.py). La grilla queda centrada en
    el mismo punto de colocacion que usaria colocar_mesa_de_crafteo
    (columnas a los costados, filas apiladas hacia arriba en Z) -- ver
    _compute_wall_grid_coords().

    La IMPORTACION/COLOCACION de cada bloque en si NO se anima aca (igual
    que la antorcha/mesa) -- este generador solo deja la metadata
    WALL_BLOCKS (una entrada por celda de la grilla, con su propia
    coordenada y su propio WALL_APPEAR_FRAME -- el frame exacto en el que
    el cuerpo esta agachado colocando ESE bloque puntual) y
    WALL_BLOCK_SOURCE (la ruta .blend elegida a mano, NO una carpeta fija
    de bloques_dinamicos como antorcha/mesa) para que
    CERDO_1SEG_OT_AutoSplitFromConfig (operators_segments.py) y
    "Reproducir recorrido" (path_recorder.py) registren/importen cada
    bloque oculto hasta su frame exacto -- nunca antes, sin trayectoria
    de lanzamiento: aparece de golpe en ese instante, plantado, fijo.
    """
    p0_full = points[0]
    p0 = p0_full['coordinates']
    p1 = points[1]['coordinates']
    filas = max(1, int(p0_full.get('pared_filas', 2) or 2))
    columnas = max(1, int(p0_full.get('pared_columnas', 2) or 2))
    blend_path_raw = p0_full.get('pared_bloque_blend_path', '') or ''
    # NUEVO (Kebyn, "elegir cuantos frames dura toda la animacion de
    # crear pared"): 0 = automatico (comportamiento de siempre, ver
    # resolve_pared_nxn_timing()); >0 = Kebyn eligio el total de frames
    # de TODA la animacion (todos los bloques) en el punto, Paso 1.
    pared_total_frames = int(p0_full.get('pared_total_frames', 0) or 0)
    num_bloques = filas * columnas

    frames_per_bloque, mid_rel, total_frames = resolve_pared_nxn_timing(
        num_bloques, pared_total_frames)
    end_frame = start_frame + total_frames - 1

    grid = _compute_wall_grid_coords(p0, p1, root_rot, filas, columnas)

    wall_blocks_meta = []
    for idx, cell in enumerate(grid):
        block_start = start_frame + idx * frames_per_bloque
        appear_frame = block_start + mid_rel
        wall_blocks_meta.append({
            'row': cell['row'],
            'col': cell['col'],
            'x': cell['x'], 'y': cell['y'], 'z': cell['z'],
            # NUEVO (fix "bloques en direcciones distintas"): heading de
            # la pared en radianes, igual para toda la grilla -- ver
            # _compute_wall_grid_coords().
            'rot_z': cell.get('rot_z', 0.0),
            'appear_frame': appear_frame,
        })

    traj = _fmt_trajectory(points)
    kf = _fmt_keyframes(_build_crear_pared_nxn_keyframes(
        num_bloques, walk_style_next, frames_per_bloque), start_frame)
    rx, ry, rz = root_rot

    _wall_blocks_lines = "".join(
        "    {{'row': {row}, 'col': {col}, "
        "'coords': {{'x': {x}, 'y': {y}, 'z': {z}}}, "
        "'rot_z': {rot_z}, "
        "'appear_frame': {appear_frame}}},\n".format(**b)
        for b in wall_blocks_meta
    )
    _wall_blocks_literal = "[\n" + _wall_blocks_lines + "]"

    _blend_path_escaped = blend_path_raw.replace('\\', '\\\\').replace("'", "\\'")

    code = f'''# -*- coding: utf-8 -*-
"""
slot_{slot_index:03d}_crear_pared_nxn.py
Cerdo_1 - Slot {slot_index}

GENERADO AUTOMATICAMENTE
Fecha de generacion: {today}

NOTA: este slot anima a Cerdo_1 agachandose y colocando, uno por uno, una
grilla de {filas}x{columnas} bloques de 1m3 en el suelo frente a el, SIN
desplazar el root (permanece parado en points[0] todo el slot). La
importacion/colocacion de cada bloque la maneja el sistema de
Lanzar/Recoger/Mantener Objetos (seg.throws) -- ver WALL_BLOCKS/
WALL_BLOCK_SOURCE mas abajo.
"""

import bpy
import math

# --- Compatibilidad Action.fcurves (eliminado en Blender 5.0+, ver slots/channelbags) ---
def _get_fcurves(target):
    anim_data = None
    action = target
    if isinstance(target, bpy.types.AnimData):
        anim_data = target
        action = anim_data.action
    if action is None:
        return []
    if hasattr(action, 'fcurves'):
        return action.fcurves
    from bpy_extras import anim_utils as _au
    slot = anim_data.action_slot if anim_data is not None else None
    if slot is None and action.slots:
        slot = action.slots[0]
    if slot is None:
        return []
    channelbag = _au.action_ensure_channelbag_for_slot(action, slot)
    return channelbag.fcurves if channelbag else []

# ============================================
# CONFIGURACION DEL SLOT
# ============================================

SLOT_INDEX = {slot_index}
START_FRAME = {start_frame}
END_FRAME = {end_frame}  # {start_frame} + {total_frames} - 1
TOTAL_FRAMES = {total_frames}

# ============================================
# DATOS DE TRAYECTORIA EMBEBIDOS - SLOT {slot_index}
# ============================================

{traj}

# ============================================
# FIN DE CONFIGURACION DEL SLOT {slot_index}
# ============================================

ANIMATION_INFO = {{
    'name': 'slot_{slot_index:03d}_crear_pared_nxn.py',
    'frame_count': {total_frames},
    'fps': 24,
    'duration_seconds': {total_frames/24:.2f},
    'entity': 'Cerdo_1',
    'slot': {slot_index},
    'movement_type': 'crear_pared_nxn',
    'narrative_importance': 'prop_placement',
    'rig_type': 'full_armature',
    'source': 'cerdo_1_rig',
    'bones_animated': 14,
    'animation_type': 'crouch_place_object_grid',
}}

# Root Location: FIJO en posicion {points[0]['index']} {(p0['x'], p0['y'], p0['z'])}
# durante los {total_frames} frames -- el personaje esta parado ahi,
# colocando la grilla de bloques uno por uno sin desplazarse.

ROOT_LOCATION_DATA = {{
    {start_frame}: ({p0['x']}, {p0['y']}, {p0['z']}),
    {end_frame}: ({p0['x']}, {p0['y']}, {p0['z']}),
}}

# Una entrada por celda de la grilla Filas x Columnas -- coordenada
# mundo del bloque y frame ABSOLUTO en el que el cuerpo esta exactamente
# agachado colocando ESE bloque puntual (consumido por
# CERDO_1SEG_OT_AutoSplitFromConfig/"Reproducir recorrido" para
# registrar/importar cada bloque oculto hasta su frame exacto).
WALL_BLOCKS = {_wall_blocks_literal}
WALL_FILAS = {filas}
WALL_COLUMNAS = {columnas}
# A diferencia de antorcha_1/mesa_de_crafteo_1 (carpeta fija
# bloques_dinamicos), la fuente de la pared es el archivo .blend elegido
# a mano por Kebyn en el punto (Paso 1, campo "Bloque .blend (1m3)") --
# se usa tal cual (normalizado con bpy.path.abspath en el consumidor).
WALL_BLOCK_SOURCE = {{
    'blend_path': '{_blend_path_escaped}',
    'object_name': None,
}}

def _compute_direction_angle(p0, p1):
    """Angulo de orientacion cardinal/diagonal para el segmento p0->p1."""
    dx = p1['x'] - p0['x']
    dy = p1['y'] - p0['y']
    if dx == 0 and dy == 0:
        return None
    ang_raw = math.degrees(math.atan2(dx, dy))
    ang_rounded = round(ang_raw / 90.0) * 90.0
    ang_diff = abs(ang_raw - ang_rounded)
    ang = ang_rounded if ang_diff < 45 else -ang_raw
    while ang >  180: ang -= 360
    while ang < -180: ang += 360
    if   ang ==  90: ang = -90
    elif ang == -90: ang =  90
    return ang

def _smoothstep_val(x):
    if x <= 0: return 0.0
    if x >= 1: return 1.0
    return x * x * (3.0 - 2.0 * x)

def _angle_diff_shortest(target, current):
    d = target - current
    while d >  180: d -= 360
    while d < -180: d += 360
    return d

# --- Orientacion por trayectoria (p0->p1) con RotationSmoother, igual
# que en colocar_mesa_de_crafteo/colocar_antorcha ---
_p0_coords = {{'x': {p0['x']}, 'y': {p0['y']}, 'z': {p0['z']}}}
_p1_coords = {{'x': {p1['x']}, 'y': {p1['y']}, 'z': {p1['z']}}}
_dir_angle  = _compute_direction_angle(_p0_coords, _p1_coords)
_base_rz    = {rz}

def _build_rotation_data():
    import math as _math
    data = {{}}
    target_rz = _dir_angle if _dir_angle is not None else _base_rz
    smoothing = 10

    prev_rot  = _base_rz
    trans_start = None
    trans_start_rot = None

    for frame in range({start_frame}, {end_frame + 1}):
        angle_diff = _angle_diff_shortest(target_rz, prev_rot)
        if abs(angle_diff) < 0.1:
            smoothed = target_rz
            trans_start = None
        else:
            if trans_start is None:
                trans_start = frame
                trans_start_rot = prev_rot
            elapsed  = frame - trans_start
            progress = min(elapsed / smoothing, 1.0)
            eased    = _smoothstep_val(progress)
            smoothed = trans_start_rot + _angle_diff_shortest(target_rz, trans_start_rot) * eased
            if progress >= 1.0:
                prev_rot   = target_rz
                trans_start = None

        data[frame] = (_math.radians({rx}), _math.radians({ry}), _math.radians(smoothed))
    return data

ROOT_ROTATION_DATA = _build_rotation_data()
ROOT_ROTATION_X = {rx}
ROOT_ROTATION_Y = {ry}
ROOT_ROTATION_Z = {rz}

{kf}


def execute_animation(player_parts, start_frame=None, end_frame=None):
    """
    Slot {slot_index}: 'Crear pared NxN bloques' de Cerdo_1 -- se agacha y
    coloca, uno por uno, una grilla de {filas}x{columnas} bloques de 1m3.
    """
    start_frame = START_FRAME
    end_frame = END_FRAME

    armature = bpy.data.objects.get("pig.arma_cerdo_1")
    if not armature or armature.type != 'ARMATURE':
        print("Error: No se encontro el Armature")
        return False

    if armature.mode != 'POSE':
        bpy.context.view_layer.objects.active = armature
        bpy.ops.object.mode_set(mode='POSE')

    cerdo_1_root = next((o for o in bpy.data.objects if o.name == 'cerdo_1' and o.type == 'EMPTY'), None)

    _arm_action_name  = f'slot_{slot_index:03d}_cerdo_1_crear_pared_nxn_arm'
    _root_action_name = f'slot_{slot_index:03d}_cerdo_1_crear_pared_nxn_root'

    if not armature.animation_data:
        armature.animation_data_create()
    _arm_existing = bpy.data.actions.get(_arm_action_name)
    if _arm_existing:
        bpy.data.actions.remove(_arm_existing)
    _arm_action = bpy.data.actions.new(name=_arm_action_name)
    armature.animation_data.action = _arm_action

    _bones_ok = 0
    for _bone_name, _frames in globals()['KEYFRAME_DATA'].items():
        _bone = armature.pose.bones.get(_bone_name)
        if not _bone:
            continue
        _bone.rotation_mode = 'XYZ'
        for _frame, _rot in _frames.items():
            _bone.rotation_euler = _rot
            _bone.keyframe_insert(data_path="rotation_euler", frame=_frame)
        _bones_ok += 1

    for _fc in _get_fcurves(_arm_action):
        for _kp in _fc.keyframe_points:
            _kp.interpolation = 'BEZIER'
            _kp.easing = 'AUTO'

    if cerdo_1_root is not None:
        if not cerdo_1_root.animation_data:
            cerdo_1_root.animation_data_create()
        _root_existing = bpy.data.actions.get(_root_action_name)
        if _root_existing:
            bpy.data.actions.remove(_root_existing)
        _root_action = bpy.data.actions.new(name=_root_action_name)
        cerdo_1_root.animation_data.action = _root_action

        for _frame in sorted(ROOT_LOCATION_DATA.keys()):
            cerdo_1_root.location = ROOT_LOCATION_DATA[_frame]
            cerdo_1_root.keyframe_insert(data_path="location", frame=_frame)
        for _frame in sorted(ROOT_ROTATION_DATA.keys()):
            cerdo_1_root.rotation_euler = ROOT_ROTATION_DATA[_frame]
            cerdo_1_root.keyframe_insert(data_path="rotation_euler", frame=_frame)

        for _fc in _get_fcurves(_root_action):
            for _kp in _fc.keyframe_points:
                _kp.interpolation = 'BEZIER'
                _kp.easing = 'AUTO'

    print(f"[Slot {slot_index}] crear_pared_nxn aplicado ({{_bones_ok}} bones, "
          f"{{start_frame}}-{{end_frame}}), {filas}x{columnas} bloques")

    # ============================================
    # EMPUJAR ACCIONES AL NLA
    # ============================================
    if armature.animation_data and armature.animation_data.action:
        _arm_done  = armature.animation_data.action
        armature.animation_data.action = None
        _arm_track = armature.animation_data.nla_tracks.new()
        _arm_track.name = f'Slot_{slot_index:03d}_arm'
        _arm_strip = _arm_track.strips.new(_arm_done.name, start_frame, _arm_done)
        _arm_strip.frame_end      = end_frame
        _arm_strip.extrapolation  = 'NOTHING'
        _arm_strip.use_auto_blend = False
        _arm_strip.blend_in       = 0
        _arm_strip.blend_out      = 0

    if cerdo_1_root and cerdo_1_root.animation_data and cerdo_1_root.animation_data.action:
        _root_done  = cerdo_1_root.animation_data.action
        cerdo_1_root.animation_data.action = None
        _root_track = cerdo_1_root.animation_data.nla_tracks.new()
        _root_track.name = f'Slot_{slot_index:03d}_root'
        _root_strip = _root_track.strips.new(_root_done.name, start_frame, _root_done)
        _root_strip.frame_end      = end_frame
        _root_strip.extrapolation  = 'HOLD_FORWARD'
        _root_strip.use_auto_blend = False
        _root_strip.blend_in       = 0
        _root_strip.blend_out      = 0

    return True
'''
    return code, end_frame


# ============================================================
# GOLPE_ESTOMAGO_1 - animacion Mixamo (14 huesos, 100 frames)
# ============================================================
# NUEVO (Kebyn): misma arquitectura que 'colocar_antorcha' -- abarca DOS
# coordenadas REALES consecutivas del recorrido (points[0]/points[1]),
# override manual de tipo_segmento (ver detect_movement_type()). El
# root/Empty "cerdo_1" queda FIJO en points[0] durante TODO el slot (no
# camina hacia points[1] -- eso lo cubre, como con colocar_antorcha, el
# tramo "caminar" que group_segments() fusiona automaticamente justo
# despues, con los mismos 2 puntos). points[1] solo se usa como
# referencia de orientacion (el personaje gira para encarar hacia ahi
# antes de golpear), igual que en colocar_antorcha.
#
# A diferencia de colocar_antorcha (que interpola 3 poses: parado ->
# pose de accion -> parado), este slot reproduce una animacion COMPLETA
# de 100 frames importada de Mixamo (golpe_estomago_1.py, 14 huesos,
# rotation_euler por frame) tal cual, sin interpolar contra una pose de
# "parado" en los extremos -- la propia animacion ya arranca y termina
# en una pose neutral razonable.
