# LEVANTARSE_1 - animacion Mixamo (14 huesos, 107 frames)
# ============================================================
# NUEVO (Kebyn): misma arquitectura que 'golpe_estomago_1' (ver seccion
# de arriba) -- abarca DOS coordenadas REALES consecutivas del recorrido
# (points[0]/points[1]), override manual de tipo_segmento (ver
# detect_movement_type()). El root/Empty "cerdo_1" queda FIJO en points[0]
# durante TODO el slot (no camina hacia points[1] -- eso lo cubre, como
# con golpe_estomago_1, el tramo "caminar" que group_segments() fusiona
# automaticamente justo despues, con los mismos 2 puntos). points[1]
# solo se usa como referencia de orientacion (el personaje gira para
# encarar hacia ahi mientras se levanta), igual que en golpe_estomago_1.
#
# Reproduce una animacion COMPLETA de 107 frames importada de Mixamo
# (levantarse_1.py, 14 huesos, rotation_euler por frame) tal cual, sin
# interpolar contra una pose de "parado" en los extremos -- la propia
# animacion ya arranca en el suelo y termina de pie.
