# ============================================================
# LEVANTARSE_2 - animacion Mixamo (14 huesos, 183 frames)
# ============================================================
# NUEVO (Kebyn): segunda variante de "levantarse", misma arquitectura
# EXACTA que LEVANTARSE_1 (ver comentario de arriba) -- abarca DOS
# coordenadas REALES consecutivas del recorrido (points[0]/points[1]),
# override manual de tipo_segmento (ver detect_movement_type()). El
# root/Empty "cerdo_1" queda FIJO en points[0] durante TODO el slot (no
# camina hacia points[1] -- eso lo cubre el tramo "caminar" que
# group_segments() fusiona automaticamente justo despues, con los
# mismos 2 puntos). points[1] solo se usa como referencia de
# orientacion (el personaje gira para encarar hacia ahi mientras se
# levanta), igual que en levantarse_1.
#
# Reproduce una animacion COMPLETA de 183 frames importada de Mixamo
# (levantarse_2.py, 14 huesos, rotation_euler por frame) tal cual, sin
# interpolar contra una pose de "parado" en los extremos -- la propia
# animacion ya arranca en el suelo y termina de pie. Frames originales
# del clip fuente 1-183, reindexados aca a 0-182 (misma convencion que
# LEVANTARSE_1_KEYFRAME_DATA).
