# ============================================================
# ARRODILLARSE_1 - animacion Mixamo (14 huesos, 49 frames)
# ============================================================
# NUEVO (Kebyn): misma arquitectura EXACTA que 'levantarse_1'/
# 'levantarse_2'/'golpe_estomago_1' -- abarca DOS coordenadas REALES
# consecutivas del recorrido (points[0]/points[1]), override manual de
# tipo_segmento (ver detect_movement_type()). El root/Empty "cerdo_1"
# queda FIJO en points[0] durante TODO el slot (no camina hacia
# points[1] -- eso lo cubre, como con los demas overrides de accion
# puntual, el tramo "caminar" que group_segments() fusiona
# automaticamente justo despues, con los mismos 2 puntos). points[1]
# solo se usa como referencia de orientacion (el personaje gira para
# encarar hacia ahi antes de arrodillarse), igual que en los demas.
#
# Reproduce una animacion COMPLETA de 49 frames importada de Mixamo
# (arrodillarse_1.py, 14 huesos, rotation_euler por frame) tal cual --
# arranca de pie y termina arrodillado, sin interpolar contra una pose
# de "parado" en los extremos.
#
# NOTA (extraccion): Leg:BR_cerdo_1 no traia bloque propio de
# keyframes en el archivo fuente (POSE_INICIO/ACCION/FIN coinciden en
# el mismo valor estatico) -- se rellena aca como constante en los 49
# frames para que quede explicitamente keyframeado. Se descarto ademas
# la entrada 'no_bone_01' del archivo fuente (no es uno de los 14
# huesos animables del rig).
