# ============================================================
# RESBALARSE_1 - animacion Mixamo (14 huesos, 51 frames)
# ============================================================
# NUEVO (Kebyn): misma arquitectura EXACTA que 'arrodillarse_1'/
# 'levantarse_1'/'levantarse_2'/'golpe_estomago_1' -- abarca DOS
# coordenadas REALES consecutivas del recorrido (points[0]/points[1]),
# override manual de tipo_segmento (ver detect_movement_type()). El
# root/Empty "cerdo_1" queda FIJO en points[0] durante TODO el slot (no
# camina hacia points[1] -- eso lo cubre, como con los demas overrides
# de accion puntual, el tramo "caminar" que group_segments() fusiona
# automaticamente justo despues, con los mismos 2 puntos). points[1]
# solo se usa como referencia de orientacion (el personaje gira para
# encarar hacia ahi antes de resbalar), igual que en los demas.
#
# Reproduce una animacion completa de 51 frames importada de Mixamo
# (resbalarse_1.py, 14 huesos, rotation_euler por frame) -- arranca de
# pie y termina caido/deslizado en el suelo.
#
# NOTA (extraccion): el archivo fuente (resbalarse_1.py) solo trae 3
# poses de referencia por hueso (POSE_INICIO/POSE_ACCION/POSE_FIN, en
# los frames locales 1/26/51) mas su propia funcion de interpolacion
# smoothstep (_interp3/_lerp/_smooth) para generar el resto. A
# diferencia de golpe_estomago_1/levantarse_1/levantarse_2/
# arrodillarse_1 (que traian los 100/107/183/49 frames ya densificados
# desde una captura real en Blender), aca se horneo (bake) 1 valor por
# frame para los 51 frames corriendo esa misma funcion de interpolacion
# del archivo fuente, para mantener la misma estructura de
# KEYFRAME_DATA plano (1 entrada por frame) que usan los demas slots de
# este bloque.
